# The cgroup limit shows 2000000/100000 = 20 CPU equivalents
# With 20 effective CPUs and max_threads=20, we get 8 match threads
# With max_threads=9, we get 8 match threads
# 
# I wonder if num_cpus::get_physical() returns 8 (because of cgroup calculations)?
# Or maybe it uses some other logic.
# 
# Let me try to implement this ourselves - we'll need to figure out what "physical CPUs" 
# returns in this environment. Let me write a minimal Rust test using std only.

cat > /tmp/rust_test/src/main.rs << 'EOF'
fn main() {
    // Standard library approach
    // In Rust, there's no built-in num_cpus function in std
    // But we can read from /sys/fs/cgroup or /proc

    // Try to read cgroup CPU count
    if let Ok(content) = std::fs::read_to_string("/sys/fs/cgroup/cpu.max") {
        let parts: Vec<&str> = content.trim().split_whitespace().collect();
        if parts.len() >= 2 {
            if let (Ok(quota), Ok(period)) = (parts[0].parse::<f64>(), parts[1].parse::<f64>()) {
                let cpus = quota / period;
                println!("Cgroup CPUs: {}", cpus);
            }
        }
    }

    // /proc/cpuinfo count
    if let Ok(content) = std::fs::read_to_string("/proc/cpuinfo") {
        let count = content.lines().filter(|l| l.starts_with("processor")).count();
        println!("/proc/cpuinfo processors: {}", count);
    }
}
EOF

