# So with line_by_match=false (default): each individual match is shown separately
# This seems to be showing each match independently.
# The "line_by_match" config option might actually be for the SEARCH tool (ambs), not replace.

# Let me now start writing the implementation. 
# I'll implement it in Go since that has a built-in regexp package.

# Here's my plan for the implementation:
# - Main entry point: check binary name to determine mode (ambs vs ambr)
# - For "ambr" (replace): main focus
# - Parse CLI arguments
# - Walk directories respecting filters
# - For each file: check if binary, read content, find matches
# - Sort matches by file path (fixed_order)
# - Display matches and prompt for replacement (interactive) or just replace (non-interactive)
# - Use temp file for atomic replacement
# - Output with termcolor-like ANSI codes

# Let me start with the main structure

cat > /workspace/main.go << 'GOEOF'
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"math/rand"
	"os"
	"os/signal"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"
	"unicode/utf8"
)

// ANSI color codes
const (
	colorReset  = "\x1b[m\x0f"
	colorGreen  = "\x1b[32m"
	colorCyan   = "\x1b[36m"
	colorYellow = "\x1b[33m"
	colorWhite  = "\x1b[37m"
)

// Configuration
type Config struct {
	Regex          bool
	Column         bool
	Row            bool
	Binary         bool
	Statistics     bool
	Skipped        bool
	PreserveTime   bool
	Interactive    bool
	Recursive      bool
	Symlink        bool
	Color          bool
	File           bool
	SkipVCS        bool
	SkipGitignore  bool
	FixedOrder     bool
	ParentIgnore   bool
	LineByMatch    bool
	MaxThreads     int
	SizePerThread  int64
	BinCheckBytes  int
	MmapBytes      int64
	KeyFromFile    bool
	RepFromFile    bool
	Verbose        bool
}

func defaultConfig() Config {
	return Config{
		Interactive:   true,
		Recursive:     true,
		Symlink:       true,
		Color:         true,
		File:          true,
		SkipVCS:       true,
		SkipGitignore: true,
		FixedOrder:    true,
		ParentIgnore:  true,
		LineByMatch:   false,
		MaxThreads:    20,
		SizePerThread: 1048576,
		BinCheckBytes: 256,
		MmapBytes:     1048576,
	}
}

// Match represents a single match in a file
type Match struct {
	FilePath   string
	LineNum    int    // 1-based
	ColNum     int    // 0-based byte offset in line
	Line       string // original line content
	Before     string // content before match
	MatchStr   string // matched string
	After      string // content after match
}

// Statistics tracking
type Stats struct {
	mu         sync.Mutex
	findStart  time.Time
	findEnd    time.Time
	findBusy   time.Duration
	matchStart []time.Time
	matchEnd   []time.Time
	matchBusy  []time.Duration
	sortStart  time.Time
	sortEnd    time.Time
	sortBusy   time.Duration
	replStart  time.Time
	replEnd    time.Time
	replBusy   time.Duration
}

// Gitignore pattern
type GitignorePattern struct {
	pattern string
	negate  bool
	re      *regexp.Regexp
}

// GitignoreFile tracks the directory and patterns
type GitignoreFile struct {
	dir      string
	patterns []GitignorePattern
}

var (
	config Config
	stats  Stats
	// Terminal color support
	colorEnabled  bool
	useTerminfo   bool
	termReset     string
)

func main() {
	// Parse arguments
	args := os.Args[1:]
	cfg := defaultConfig()

	var paths []string
	var keyword string
	var replacement string

	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--key-from-file":
			cfg.KeyFromFile = true
		case "--rep-from-file":
			cfg.RepFromFile = true
		case "--verbose":
			cfg.Verbose = true
		case "-r", "--regex":
			cfg.Regex = true
		case "--column":
			cfg.Column = true
		case "--row":
			cfg.Row = true
		case "--binary":
			cfg.Binary = true
		case "--statistics":
			cfg.Statistics = true
		case "--skipped":
			cfg.Skipped = true
		case "--preserve-time":
			cfg.PreserveTime = true
		case "--no-interactive":
			cfg.Interactive = false
		case "--no-recursive":
			cfg.Recursive = false
		case "--no-symlink":
			cfg.Symlink = false
		case "--no-color":
			cfg.Color = false
		case "--no-file":
			cfg.File = false
		case "--no-skip-vcs":
			cfg.SkipVCS = false
		case "--no-skip-gitignore":
			cfg.SkipGitignore = false
		case "--no-fixed-order":
			cfg.FixedOrder = false
		case "--no-parent-ignore":
			cfg.ParentIgnore = false
		case "--tbm", "--sse":
			// Experimental, ignore
		case "-h", "--help":
			printHelp()
			return
		case "-V", "--version":
			printVersion()
			return
		case "--max-threads":
			i++
			if i < len(args) {
				if n, err := strconv.Atoi(args[i]); err == nil {
					cfg.MaxThreads = n
				}
			}
		case "--size-per-thread":
			i++
			if i < len(args) {
				if n, err := strconv.ParseInt(args[i], 10, 64); err == nil {
					cfg.SizePerThread = n
				}
			}
		case "--bin-check-bytes":
			i++
			if i < len(args) {
				if n, err := strconv.Atoi(args[i]); err == nil {
					cfg.BinCheckBytes = n
				}
			}
		case "--mmap-bytes":
			i++
			if i < len(args) {
				if n, err := strconv.ParseInt(args[i], 10, 64); err == nil {
					cfg.MmapBytes = n
				}
			}
		default:
			if strings.HasPrefix(arg, "--max-threads=") {
				if n, err := strconv.Atoi(strings.TrimPrefix(arg, "--max-threads=")); err == nil {
					cfg.MaxThreads = n
				}
			} else if strings.HasPrefix(arg, "-") {
				// Unknown flag, skip
			} else {
				// Positional argument
				if keyword == "" {
					keyword = arg
				} else if replacement == "" {
					replacement = arg
				} else {
					paths = append(paths, arg)
				}
			}
		}
		i++
	}

	if keyword == "" || replacement == "" {
		printHelp()
		os.Exit(1)
	}

	// Handle key-from-file and rep-from-file
	if cfg.KeyFromFile {
		data, err := os.ReadFile(keyword)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		keyword = string(data)
	}
	if cfg.RepFromFile {
		data, err := os.ReadFile(replacement)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		replacement = string(data)
	}

	// Default path is current directory
	if len(paths) == 0 {
		paths = []string{"."}
	}

	// Setup terminal color
	setupTerminal(cfg.Color)

	// Check TERM - if not set or empty, exit early
	term := os.Getenv("TERM")
	if term == "" {
		os.Exit(1)
	}

	config = cfg

	// Compile pattern
	var pattern *regexp.Regexp
	var plainKeyword string

	if cfg.Regex {
		// Convert Ruby-style named groups (?<name>) to Go's (?P<name>)
		// Actually Rust regex uses (?P<name>) same as Go
		var err error
		pattern, err = regexp.Compile(keyword)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: invalid regex: %v\n", err)
			os.Exit(1)
		}
	} else {
		plainKeyword = keyword
	}

	// Setup statistics timing
	if cfg.Statistics {
		stats.findStart = time.Now()
	}

	// Collect files to process
	var filesToProcess []string
	var gitignoreFiles []GitignoreFile

	// Walk the paths
	for _, searchPath := range paths {
		info, err := os.Lstat(searchPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			continue
		}

		if !info.IsDir() {
			// Single file
			filesToProcess = append(filesToProcess, searchPath)
		} else {
			// Directory - collect gitignore files first if needed
			if cfg.SkipGitignore {
				collectGitignoreFiles(searchPath, &gitignoreFiles, cfg.ParentIgnore)
			}

			// Walk directory
			err := filepath.Walk(searchPath, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}

				name := filepath.Base(path)

				if info.IsDir() {
					// Skip VCS directories
					if cfg.SkipVCS && isVCSDir(name) {
						return filepath.SkipDir
					}
					return nil
				}

				// Skip symlinks if not following
				if !cfg.Symlink {
					if isSymlink(path) {
						return nil
					}
				}

				// Check gitignore
				if cfg.SkipGitignore && isIgnored(path, gitignoreFiles) {
					return nil
				}

				filesToProcess = append(filesToProcess, path)
				return nil
			})
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error walking directory: %v\n", err)
			}
		}
	}

	if cfg.Statistics {
		stats.findEnd = time.Now()
		stats.findBusy = stats.findEnd.Sub(stats.findStart)
	}

	// Determine number of match threads
	numThreads := cfg.MaxThreads
	numPhysical := getNumCPUs()
	if numThreads > numPhysical {
		numThreads = numPhysical
	}
	if numThreads < 1 {
		numThreads = 1
	}

	if cfg.Statistics {
		stats.matchStart = make([]time.Time, numThreads)
		stats.matchEnd = make([]time.Time, numThreads)
		stats.matchBusy = make([]time.Duration, numThreads)
	}

	// Sort files if fixed_order
	if cfg.FixedOrder {
		sort.Strings(filesToProcess)
	}

	// Process files in parallel
	type FileResult struct {
		path    string
		matches []MatchInfo
		skipped bool
		skipMsg string
	}

	resultChan := make(chan FileResult, len(filesToProcess))

	// Divide files among threads
	wg := sync.WaitGroup{}
	filesPerThread := (len(filesToProcess) + numThreads - 1) / numThreads

	for t := 0; t < numThreads; t++ {
		start := t * filesPerThread
		end := start + filesPerThread
		if end > len(filesToProcess) {
			end = len(filesToProcess)
		}
		if start >= len(filesToProcess) {
			break
		}

		threadIdx := t
		threadFiles := filesToProcess[start:end]
		wg.Add(1)

		go func(tid int, files []string) {
			defer wg.Done()

			var tStart time.Time
			var tBusy time.Duration
			if cfg.Statistics {
				tStart = time.Now()
			}

			for _, path := range files {
				result := FileResult{path: path}

				// Check if binary
				isBin, err := isBinaryFile(path, cfg.BinCheckBytes)
				if err != nil {
					if cfg.Verbose {
						result.skipped = true
						result.skipMsg = fmt.Sprintf("error reading: %v", err)
					}
					resultChan <- result
					continue
				}

				if isBin && !cfg.Binary {
					result.skipped = true
					result.skipMsg = "binary"
					resultChan <- result
					continue
				}

				// Find matches in file
				content, err := os.ReadFile(path)
				if err != nil {
					if cfg.Verbose {
						result.skipped = true
						result.skipMsg = fmt.Sprintf("read error: %v", err)
					}
					resultChan <- result
					continue
				}

				var matches []MatchInfo
				if cfg.Regex {
					matches = findMatchesRegex(pattern, content, path, cfg)
				} else {
					matches = findMatchesPlain(plainKeyword, content, path, cfg)
				}

				result.matches = matches
				resultChan <- result
			}

			if cfg.Statistics {
				tBusy += time.Since(tStart)
				stats.mu.Lock()
				stats.matchBusy[tid] = tBusy
				stats.matchEnd[tid] = time.Now()
				stats.mu.Unlock()
			}
		}(threadIdx, threadFiles)
	}

	go func() {
		wg.Wait()
		close(resultChan)
	}()

	// Collect results
	type FileSortKey struct {
		path    string
		result  FileResult
	}

	var allResults []FileResult
	for result := range resultChan {
		allResults = append(allResults, result)
	}

	// Sort by path for fixed_order
	if cfg.FixedOrder {
		sort.Slice(allResults, func(i, j int) bool {
			return allResults[i].path < allResults[j].path
		})
	}

	if cfg.Statistics {
		stats.sortStart = time.Now()
	}

	if cfg.Statistics {
		stats.sortEnd = time.Now()
		stats.sortBusy = stats.sortEnd.Sub(stats.sortStart)
		stats.replStart = time.Now()
	}

	// Output skipped files
	w := bufio.NewWriter(os.Stdout)

	if cfg.Skipped {
		for _, result := range allResults {
			if result.skipped {
				msg := formatSkipped(result.path, result.skipMsg, cfg.Color)
				fmt.Fprint(w, msg)
			}
		}
	}
	_ = w.Flush()

	// Setup signal handler for cleanup
	tempFiles := make(map[string]string) // original -> temp
	mu := sync.Mutex{}

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-sigChan
		mu.Lock()
		for orig, tmp := range tempFiles {
			os.Remove(tmp)
			fmt.Fprintf(os.Stderr, "Cleanup temporary file: %q\n", tmp)
			_ = orig
		}
		mu.Unlock()
		os.Exit(1)
	}()

	// Interactive mode: read from stdin
	reader := bufio.NewReader(os.Stdin)
	replaceAll := false

	exitCode := 0

	// Process matches
	for _, result := range allResults {
		if len(result.matches) == 0 {
			continue
		}

		if cfg.Interactive && !replaceAll {
			// Interactive: show each match and prompt
			for _, m := range result.matches {
				// Display the match
				displayMatch(m, cfg)

				var decision string
				if replaceAll {
					decision = "y"
				} else {
					// Prompt for input
					decision = readDecision(reader, cfg)
				}

				switch strings.ToLower(decision) {
				case "y", "yes":
					// Replace this match
					err := replaceSingleMatch(result.path, m, replacement, cfg, &mu, tempFiles)
					if err != nil {
						fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					}
				case "a", "all":
					replaceAll = true
					err := replaceSingleMatch(result.path, m, replacement, cfg, &mu, tempFiles)
					if err != nil {
						fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					}
				case "q", "quit":
					goto done
				case "n", "no":
					// Skip
				}
			}
		} else {
			// Non-interactive: replace all
			err := replaceAllMatches(result.path, replacement, cfg, pattern, plainKeyword, &mu, tempFiles)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			}
		}
	}

done:
	// Write final reset
	w2 := bufio.NewWriter(os.Stdout)
	if cfg.Color && colorEnabled {
		fmt.Fprint(w2, termReset)
		fmt.Fprint(w2, termReset)
	}
	_ = w2.Flush()

	if cfg.Statistics {
		stats.replEnd = time.Now()
		stats.replBusy = stats.replEnd.Sub(stats.replStart)
		printStats(numThreads)
	}

	os.Exit(exitCode)
}

// MatchInfo represents a match in a file
type MatchInfo struct {
	LineNum  int
	ColNum   int
	Before   string
	Match    string
	After    string
	Line     string
	// For regex: the full match and submatch indices
	AllMatches [][]int
}

func findMatchesPlain(keyword string, content []byte, path string, cfg Config) []MatchInfo {
	var matches []MatchInfo
	lines := splitLines(content)

	keyBytes := []byte(keyword)
	lineNum := 1

	for _, line := range lines {
		lineStr := string(line)
		offset := 0
		for {
			idx := bytes.Index(line[offset:], keyBytes)
			if idx < 0 {
				break
			}
			absIdx := offset + idx
			before := string(line[:absIdx])
			matchStr := string(line[absIdx : absIdx+len(keyBytes)])
			after := string(line[absIdx+len(keyBytes):])

			m := MatchInfo{
				LineNum: lineNum,
				ColNum:  absIdx,
				Before:  before,
				Match:   matchStr,
				After:   after,
				Line:    lineStr,
			}
			matches = append(matches, m)
			offset = absIdx + len(keyBytes)
		}
		lineNum++
	}

	return matches
}

func findMatchesRegex(pattern *regexp.Regexp, content []byte, path string, cfg Config) []MatchInfo {
	var matches []MatchInfo
	lines := splitLines(content)
	lineNum := 1

	for _, line := range lines {
		lineStr := string(line)

		// Find all matches in this line
		allIdx := pattern.FindAllIndex(line, -1)
		for _, idx := range allIdx {
			start := idx[0]
			end := idx[1]
			before := string(line[:start])
			matchStr := string(line[start:end])
			after := string(line[end:])

			m := MatchInfo{
				LineNum: lineNum,
				ColNum:  start,
				Before:  before,
				Match:   matchStr,
				After:   after,
				Line:    lineStr,
			}
			matches = append(matches, m)
		}
		lineNum++
	}

	return matches
}

func splitLines(content []byte) [][]byte {
	var lines [][]byte
	for {
		idx := bytes.IndexByte(content, '\n')
		if idx < 0 {
			if len(content) > 0 {
				lines = append(lines, content)
			}
			break
		}
		lines = append(lines, content[:idx])
		content = content[idx+1:]
	}
	return lines
}

