func formatMatch(m MatchInfo, cfg Config, filePath string) string {
	var buf strings.Builder

	// Compute the prefix (for alignment)
	var prefix string

	if cfg.File {
		if cfg.Row && cfg.Column {
			prefix = fmt.Sprintf("%s: %d:%d:", filePath, m.LineNum, m.ColNum)
		} else if cfg.Row {
			prefix = fmt.Sprintf("%s: %d:", filePath, m.LineNum)
		} else if cfg.Column {
			prefix = fmt.Sprintf("%s: %d:", filePath, m.ColNum)
		} else {
			prefix = fmt.Sprintf("%s: ", filePath)
		}
	} else {
		if cfg.Row && cfg.Column {
			prefix = fmt.Sprintf("%d:%d:", m.LineNum, m.ColNum)
		} else if cfg.Row {
			prefix = fmt.Sprintf("%d:", m.LineNum)
		} else if cfg.Column {
			prefix = fmt.Sprintf("%d:", m.ColNum)
		} else {
			prefix = "    "
		}
	}

	// Arrow padding
	arrowPad := strings.Repeat(" ", len(prefix)-3) + "-> "
	if len(prefix) < 4 {
		arrowPad = " -> "
	}
	if !cfg.File && !cfg.Row && !cfg.Column {
		arrowPad = " -> "
	}

	// Compute replacement text
	replContent := m.Before + "REPLACEMENT" + m.After

	// Line 1: prefix + content
	if cfg.Color {
		// Line 1 parts
		if cfg.File {
			buf.WriteString(colorGreen + filePath + colorCyan)
			if cfg.Row && cfg.Column {
				buf.WriteString(fmt.Sprintf(": %d:%d:", m.LineNum, m.ColNum))
			} else if cfg.Row {
				buf.WriteString(fmt.Sprintf(": %d:", m.LineNum))
			} else if cfg.Column {
				buf.WriteString(fmt.Sprintf(": %d:", m.ColNum))
			} else {
				buf.WriteString(": ")
			}
		} else {
			if cfg.Row && cfg.Column {
				buf.WriteString(fmt.Sprintf("%d:%d:", m.LineNum, m.ColNum))
			} else if cfg.Row {
				buf.WriteString(fmt.Sprintf("%d:", m.LineNum))
			} else if cfg.Column {
				buf.WriteString(fmt.Sprintf("%d:", m.ColNum))
			} else {
				buf.WriteString("    ")
			}
		}
		buf.WriteString(colorWhite + m.Before + colorYellow + m.Match + colorWhite + m.After)
	} else {
		buf.WriteString(prefix + m.Line)
	}

	buf.WriteString("\n")

	// Line 2: arrow + replacement
	if cfg.Color {
		buf.WriteString(colorCyan + arrowPad + colorYellow)
		buf.WriteString(m.Before + "REPLACEMENT" + m.After)
	} else {
		buf.WriteString(arrowPad + replContent)
	}

	_ = replContent

	buf.WriteString("\n")

	return buf.String()
}

