func replaceSingleMatch(filePath string, m MatchInfo, replacement string, cfg Config, mu *sync.Mutex, tempFiles map[string]string) error {
	// Read current file content
	content, err := os.ReadFile(filePath)
	if err != nil {
		return err
	}

	lines := splitLines(content)
	if m.LineNum < 1 || m.LineNum > len(lines) {
		return fmt.Errorf("line number out of range")
	}

	lineIdx := m.LineNum - 1
	line := lines[lineIdx]

	// Verify the match is still there at the expected position
	keyLen := len(m.Match)
	if m.ColNum+keyLen > len(line) {
		return fmt.Errorf("match no longer at expected position")
	}

	// Replace the specific occurrence
	newLine := string(line[:m.ColNum]) + replacement + string(line[m.ColNum+keyLen:])
	lines[lineIdx] = []byte(newLine)

	// Write to temp file
	tmpPath, err := writeToTemp(filePath, lines, content)
	if err != nil {
		return err
	}

	mu.Lock()
	tempFiles[filePath] = tmpPath
	mu.Unlock()

	// Get original file info for permissions and time
	info, err := os.Stat(filePath)
	if err != nil {
		os.Remove(tmpPath)
		return err
	}

	// Preserve time if requested
	var origTime time.Time
	if cfg.PreserveTime {
		origTime = info.ModTime()
	}

	// Move temp file to original
	err = os.Rename(tmpPath, filePath)
	if err != nil {
		os.Remove(tmpPath)
		return err
	}

	mu.Lock()
	delete(tempFiles, filePath)
	mu.Unlock()

	if cfg.PreserveTime {
		os.Chtimes(filePath, origTime, origTime)
	}

	return nil
}

func replaceAllMatches(filePath, replacement string, cfg Config, pattern *regexp.Regexp, plainKeyword string, mu *sync.Mutex, tempFiles map[string]string) error {
	content, err := os.ReadFile(filePath)
	if err != nil {
		return err
	}

	var newContent []byte
	if cfg.Regex {
		newContent = replaceRegex(pattern, content, replacement)
	} else {
		newContent = bytes.ReplaceAll(content, []byte(plainKeyword), []byte(replacement))
	}

	if bytes.Equal(content, newContent) {
		return nil
	}

	// Write to temp file
	tmpPath := genTempPath(filePath)

	mu.Lock()
	tempFiles[filePath] = tmpPath
	mu.Unlock()

	// Get original file info
	info, err := os.Stat(filePath)
	if err != nil {
		return err
	}

	var origTime time.Time
	if cfg.PreserveTime {
		origTime = info.ModTime()
	}

	err = os.WriteFile(tmpPath, newContent, info.Mode())
	if err != nil {
		return err
	}

	err = os.Rename(tmpPath, filePath)
	if err != nil {
		os.Remove(tmpPath)
		mu.Lock()
