	}

	mu.Lock()
	delete(tempFiles, filePath)
	mu.Unlock()

	if cfg.PreserveTime {
		os.Chtimes(filePath, origTime, origTime)
	}

	return nil
}

func replaceRegex(pattern *regexp.Regexp, content []byte, replacement string) []byte {
	// Handle $1, ${1}, $name, ${name} backreferences
	return pattern.ReplaceAll(content, buildReplacementTemplate(pattern, replacement))
}

func buildReplacementTemplate(pattern *regexp.Regexp, replacement string) []byte {
	// Convert $name and $1 to Go's ${name} format
	// Go's regexp uses $1 and ${1} already, and also ${name}
	// Rust regex supports $name, ${name}, $1, ${1}
	// We need to handle the conversion

	// For Go regexp: the replacement string uses ${1} for group 1, ${name} for named group
	// Our input may have $name (without braces)

	// Convert $name -> ${name} (but not $$)
	re := regexp.MustCompile(`\$(?:(\d+)|([a-zA-Z_][a-zA-Z0-9_]*))`)
	result := re.ReplaceAllStringFunc(replacement, func(s string) string {
		if s == "$$" {
			return "$$"
		}
		inner := s[1:]
		if inner[0] == '{' {
			return s // already braced
		}
		return "${" + inner + "}"
	})

	return []byte(result)
}

func writeToTemp(filePath string, lines [][]byte, original []byte) (string, error) {
	tmpPath := genTempPath(filePath)

	info, err := os.Stat(filePath)
	if err != nil {
		return "", err
	}

	f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, info.Mode())
	if err != nil {
		return "", err
	}
	defer f.Close()

	// Reconstruct content
	// Detect original line endings
	hasCRLF := bytes.Contains(original, []byte("\r\n"))

	for i, line := range lines {
		if _, err := f.Write(line); err != nil {
			return "", err
		}
		if i < len(lines)-1 {
			if hasCRLF {
				if _, err := f.Write([]byte("\r\n")); err != nil {
					return "", err
				}
			} else {
				if _, err := f.Write([]byte("\n")); err != nil {
					return "", err
				}
			}
		}
	}

	// Add trailing newline if original had one
	if len(original) > 0 && original[len(original)-1] == '\n' {
		if hasCRLF {
			f.Write([]byte("\r\n"))
		} else {
			f.Write([]byte("\n"))
		}
	}

	return tmpPath, nil
}

func genTempPath(filePath string) string {
	dir := filepath.Dir(filePath)
	const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
	b := make([]byte, 6)
	for i := range b {
		b[i] = chars[rand.Intn(len(chars))]
	}
	return filepath.Join(dir, ".tmp"+string(b))
}

func isBinaryFile(path string, checkBytes int) (bool, error) {
	f, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer f.Close()

	buf := make([]byte, checkBytes)
	n, err := f.Read(buf)
	if err != nil && err != io.EOF {
		return false, err
	}

	// Check for null bytes
	for _, b := range buf[:n] {
		if b == 0 {
			return true, nil
		}
	}

	return false, nil
}

