func isSymlink(path string) bool {
	info, err := os.Lstat(path)
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeSymlink != 0
}

func collectGitignoreFiles(dir string, files *[]GitignoreFile, parentIgnore bool) {
	// Search for .gitignore files in dir and parents
	if parentIgnore {
		// Walk up to find parent .gitignore files
		current := dir
		var parents []string
		for {
			parent := filepath.Dir(current)
			if parent == current {
				break
			}
			parents = append([]string{parent}, parents...)
			current = parent
		}
		for _, p := range parents {
			loadGitignoreFile(p, files)
		}
	}

	// Load .gitignore in the search directory and subdirs
	loadGitignoreFilesRecursive(dir, files)
}

func loadGitignoreFilesRecursive(dir string, files *[]GitignoreFile) {
	loadGitignoreFile(dir, files)

	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	for _, e := range entries {
		if e.IsDir() && !isVCSDir(e.Name()) {
			loadGitignoreFilesRecursive(filepath.Join(dir, e.Name()), files)
		}
	}
}

func loadGitignoreFile(dir string, files *[]GitignoreFile) {
	gitignorePath := filepath.Join(dir, ".gitignore")
	data, err := os.ReadFile(gitignorePath)
	if err != nil {
		return
	}

	var patterns []GitignorePattern
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		negate := false
		if strings.HasPrefix(line, "!") {
			negate = true
			line = line[1:]
		}

		// Convert glob to regex
		reStr := globToRegex(line)
		re, err := regexp.Compile(reStr)
		if err != nil {
			continue
		}

		patterns = append(patterns, GitignorePattern{
			pattern: line,
			negate:  negate,
			re:      re,
		})
	}

	if len(patterns) > 0 {
		*files = append(*files, GitignoreFile{dir: dir, patterns: patterns})
	}
}

func globToRegex(glob string) string {
	var re strings.Builder
	re.WriteString("(?i)^")

	for i := 0; i < len(glob); i++ {
		c := glob[i]
		switch c {
		case '*':
			if i+1 < len(glob) && glob[i+1] == '*' {
				re.WriteString(".*")
				i++
			} else {
				re.WriteString("[^/]*")
			}
		case '?':
			re.WriteString("[^/]")
		case '.':
			re.WriteString("\\.")
		case '/':
			re.WriteString("/")
		default:
			re.WriteByte(c)
		}
	}

	re.WriteString("(/.*)?$")
	return re.String()
}

func isIgnored(path string, gitignoreFiles []GitignoreFile) bool {
	for _, gf := range gitignoreFiles {
		rel, err := filepath.Rel(gf.dir, path)
		if err != nil {
			continue
		}

		for _, p := range gf.patterns {
			// Check if pattern matches the filename or path
			if p.re.MatchString(rel) || p.re.MatchString(filepath.Base(path)) {
				if p.negate {
					return false
				}
				return true
			}
		}
	}
	return false
}

