func defaultConfig() Config {
	return Config{
		Interactive:   true,
		Recursive:     true,
		Symlink:       true,
		Color:         true,
		File:          true,
		SkipVCS:       true,
		SkipGitignore: true,
		FixedOrder:    true,
		ParentIgnore:  true,
		LineByMatch:   false,
		MaxThreads:    20,
		SizePerThread: 1048576,
		BinCheckBytes: 256,
		MmapBytes:     1048576,
	}
}

// Match represents a single match in a file
type Match struct {
	FilePath   string
	LineNum    int    // 1-based
	ColNum     int    // 0-based byte offset in line
	Line       string // original line content
	Before     string // content before match
	MatchStr   string // matched string
	After      string // content after match
}

// Statistics tracking
type Stats struct {
	mu         sync.Mutex
	findStart  time.Time
	findEnd    time.Time
	findBusy   time.Duration
	matchStart []time.Time
	matchEnd   []time.Time
	matchBusy  []time.Duration
	sortStart  time.Time
	sortEnd    time.Time
	sortBusy   time.Duration
	replStart  time.Time
	replEnd    time.Time
	replBusy   time.Duration
}

// Gitignore pattern
type GitignorePattern struct {
	pattern string
	negate  bool
	re      *regexp.Regexp
}

// GitignoreFile tracks the directory and patterns
type GitignoreFile struct {
	dir      string
	patterns []GitignorePattern
}

var (
	config Config
	stats  Stats
	// Terminal color support
	colorEnabled  bool
	useTerminfo   bool
	termReset     string
)

func main() {
	// Parse arguments
	args := os.Args[1:]
	cfg := defaultConfig()

	var paths []string
	var keyword string
	var replacement string

	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--key-from-file":
			cfg.KeyFromFile = true
		case "--rep-from-file":
			cfg.RepFromFile = true
		case "--verbose":
			cfg.Verbose = true
		case "-r", "--regex":
			cfg.Regex = true
		case "--column":
			cfg.Column = true
		case "--row":
			cfg.Row = true
		case "--binary":
			cfg.Binary = true
		case "--statistics":
			cfg.Statistics = true
		case "--skipped":
			cfg.Skipped = true
		case "--preserve-time":
			cfg.PreserveTime = true
		case "--no-interactive":
			cfg.Interactive = false
		case "--no-recursive":
			cfg.Recursive = false
		case "--no-symlink":
			cfg.Symlink = false
		case "--no-color":
			cfg.Color = false
		case "--no-file":
			cfg.File = false
		case "--no-skip-vcs":
			cfg.SkipVCS = false
		case "--no-skip-gitignore":
			cfg.SkipGitignore = false
		case "--no-fixed-order":
			cfg.FixedOrder = false
		case "--no-parent-ignore":
			cfg.ParentIgnore = false
		case "--tbm", "--sse":
			// Experimental, ignore
		case "-h", "--help":
			printHelp()
			return
		case "-V", "--version":
			printVersion()
			return
		case "--max-threads":
			i++
			if i < len(args) {
				if n, err := strconv.Atoi(args[i]); err == nil {
					cfg.MaxThreads = n
				}
			}
		case "--size-per-thread":
			i++
			if i < len(args) {
				if n, err := strconv.ParseInt(args[i], 10, 64); err == nil {
					cfg.SizePerThread = n
				}
			}
		case "--bin-check-bytes":
			i++
			if i < len(args) {
				if n, err := strconv.Atoi(args[i]); err == nil {
					cfg.BinCheckBytes = n
				}
			}
		case "--mmap-bytes":
			i++
			if i < len(args) {
				if n, err := strconv.ParseInt(args[i], 10, 64); err == nil {
					cfg.MmapBytes = n
				}
			}
		default:
			if strings.HasPrefix(arg, "--max-threads=") {
				if n, err := strconv.Atoi(strings.TrimPrefix(arg, "--max-threads=")); err == nil {
					cfg.MaxThreads = n
				}
			} else if strings.HasPrefix(arg, "-") {
				// Unknown flag, skip
			} else {
				// Positional argument
				if keyword == "" {
					keyword = arg
				} else if replacement == "" {
					replacement = arg
				} else {
					paths = append(paths, arg)
				}
			}
		}
		i++
	}

	if keyword == "" || replacement == "" {
		printHelp()
		os.Exit(1)
	}

	// Handle key-from-file and rep-from-file
	if cfg.KeyFromFile {
		data, err := os.ReadFile(keyword)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		keyword = string(data)
	}
	if cfg.RepFromFile {
		data, err := os.ReadFile(replacement)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		replacement = string(data)
	}

	// Default path is current directory
	if len(paths) == 0 {
		paths = []string{"."}
	}

	// Setup terminal color
	setupTerminal(cfg.Color)

	// Check TERM - if not set or empty, exit early
	term := os.Getenv("TERM")
	if term == "" {
		os.Exit(1)
	}

	config = cfg

	// Compile pattern
	var pattern *regexp.Regexp
	var plainKeyword string

	if cfg.Regex {
		// Convert Ruby-style named groups (?<name>) to Go's (?P<name>)
		// Actually Rust regex uses (?P<name>) same as Go
		var err error
		pattern, err = regexp.Compile(keyword)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: invalid regex: %v\n", err)
			os.Exit(1)
		}
	} else {
		plainKeyword = keyword
	}

	// Setup statistics timing
	if cfg.Statistics {
		stats.findStart = time.Now()
	}

	// Collect files to process
	var filesToProcess []string
	var gitignoreFiles []GitignoreFile

	// Walk the paths
	for _, searchPath := range paths {
		info, err := os.Lstat(searchPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			continue
		}

		if !info.IsDir() {
			// Single file
			filesToProcess = append(filesToProcess, searchPath)
		} else {
			// Directory - collect gitignore files first if needed
			if cfg.SkipGitignore {
				collectGitignoreFiles(searchPath, &gitignoreFiles, cfg.ParentIgnore)
			}

			// Walk directory
			err := filepath.Walk(searchPath, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}

				name := filepath.Base(path)

				if info.IsDir() {
					// Skip VCS directories
					if cfg.SkipVCS && isVCSDir(name) {
						return filepath.SkipDir
					}
					return nil
				}

				// Skip symlinks if not following
				if !cfg.Symlink {
					if isSymlink(path) {
						return nil
					}
				}

				// Check gitignore
				if cfg.SkipGitignore && isIgnored(path, gitignoreFiles) {
					return nil
				}

				filesToProcess = append(filesToProcess, path)
				return nil
			})
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error walking directory: %v\n", err)
			}
		}
	}

	if cfg.Statistics {
		stats.findEnd = time.Now()
		stats.findBusy = stats.findEnd.Sub(stats.findStart)
	}

	// Determine number of match threads
	numThreads := cfg.MaxThreads
	numPhysical := getNumCPUs()
	if numThreads > numPhysical {
		numThreads = numPhysical
	}
	if numThreads < 1 {
		numThreads = 1
	}

	if cfg.Statistics {
		stats.matchStart = make([]time.Time, numThreads)
		stats.matchEnd = make([]time.Time, numThreads)
		stats.matchBusy = make([]time.Duration, numThreads)
	}

	// Sort files if fixed_order
	if cfg.FixedOrder {
		sort.Strings(filesToProcess)
	}

	// Process files in parallel
	type FileResult struct {
		path    string
		matches []MatchInfo
		skipped bool
		skipMsg string
	}

	resultChan := make(chan FileResult, len(filesToProcess))

	// Divide files among threads
	wg := sync.WaitGroup{}
	filesPerThread := (len(filesToProcess) + numThreads - 1) / numThreads

	for t := 0; t < numThreads; t++ {
		start := t * filesPerThread
		end := start + filesPerThread
		if end > len(filesToProcess) {
			end = len(filesToProcess)
		}
		if start >= len(filesToProcess) {
			break
		}

		threadIdx := t
		threadFiles := filesToProcess[start:end]
		wg.Add(1)

		go func(tid int, files []string) {
			defer wg.Done()

			var tStart time.Time
			var tBusy time.Duration
			if cfg.Statistics {
				tStart = time.Now()
			}

			for _, path := range files {
				result := FileResult{path: path}

				// Check if binary
				isBin, err := isBinaryFile(path, cfg.BinCheckBytes)
				if err != nil {
					if cfg.Verbose {
						result.skipped = true
						result.skipMsg = fmt.Sprintf("error reading: %v", err)
					}
					resultChan <- result
					continue
				}

				if isBin && !cfg.Binary {
					result.skipped = true
					result.skipMsg = "binary"
					resultChan <- result
					continue
				}

				// Find matches in file
				content, err := os.ReadFile(path)
				if err != nil {
					if cfg.Verbose {
						result.skipped = true
						result.skipMsg = fmt.Sprintf("read error: %v", err)
					}
					resultChan <- result
					continue
				}

				var matches []MatchInfo
				if cfg.Regex {
					matches = findMatchesRegex(pattern, content, path, cfg)
				} else {
					matches = findMatchesPlain(plainKeyword, content, path, cfg)
				}

				result.matches = matches
				resultChan <- result
			}

			if cfg.Statistics {
				tBusy += time.Since(tStart)
				stats.mu.Lock()
				stats.matchBusy[tid] = tBusy
				stats.matchEnd[tid] = time.Now()
				stats.mu.Unlock()
			}
		}(threadIdx, threadFiles)
	}

	go func() {
		wg.Wait()
		close(resultChan)
	}()

	// Collect results
	type FileSortKey struct {
		path    string
		result  FileResult
	}

	var allResults []FileResult
	for result := range resultChan {
		allResults = append(allResults, result)
	}

	// Sort by path for fixed_order
	if cfg.FixedOrder {
		sort.Slice(allResults, func(i, j int) bool {
			return allResults[i].path < allResults[j].path
		})
	}

	if cfg.Statistics {
		stats.sortStart = time.Now()
	}

	if cfg.Statistics {
		stats.sortEnd = time.Now()
		stats.sortBusy = stats.sortEnd.Sub(stats.sortStart)
		stats.replStart = time.Now()
	}

	// Output skipped files
	w := bufio.NewWriter(os.Stdout)

	if cfg.Skipped {
		for _, result := range allResults {
			if result.skipped {
				msg := formatSkipped(result.path, result.skipMsg, cfg.Color)
				fmt.Fprint(w, msg)
			}
		}
	}
	_ = w.Flush()

	// Setup signal handler for cleanup
	tempFiles := make(map[string]string) // original -> temp
	mu := sync.Mutex{}

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-sigChan
		mu.Lock()
		for orig, tmp := range tempFiles {
			os.Remove(tmp)
			fmt.Fprintf(os.Stderr, "Cleanup temporary file: %q\n", tmp)
			_ = orig
		}
		mu.Unlock()
		os.Exit(1)
	}()

	// Interactive mode: read from stdin
	reader := bufio.NewReader(os.Stdin)
	replaceAll := false

	exitCode := 0

	// Process matches
	for _, result := range allResults {
		if len(result.matches) == 0 {
			continue
		}

		if cfg.Interactive && !replaceAll {
			// Interactive: show each match and prompt
			for _, m := range result.matches {
				// Display the match
				displayMatch(m, cfg)

				var decision string
				if replaceAll {
					decision = "y"
				} else {
					// Prompt for input
					decision = readDecision(reader, cfg)
				}

				switch strings.ToLower(decision) {
				case "y", "yes":
					// Replace this match
					err := replaceSingleMatch(result.path, m, replacement, cfg, &mu, tempFiles)
					if err != nil {
						fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					}
				case "a", "all":
					replaceAll = true
					err := replaceSingleMatch(result.path, m, replacement, cfg, &mu, tempFiles)
					if err != nil {
						fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					}
				case "q", "quit":
					goto done
				case "n", "no":
					// Skip
				}
			}
		} else {
			// Non-interactive: replace all
			err := replaceAllMatches(result.path, replacement, cfg, pattern, plainKeyword, &mu, tempFiles)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			}
		}
	}

done:
	// Write final reset
	w2 := bufio.NewWriter(os.Stdout)
	if cfg.Color && colorEnabled {
		fmt.Fprint(w2, termReset)
		fmt.Fprint(w2, termReset)
	}
	_ = w2.Flush()

	if cfg.Statistics {
		stats.replEnd = time.Now()
		stats.replBusy = stats.replEnd.Sub(stats.replStart)
		printStats(numThreads)
	}

	os.Exit(exitCode)
}

// MatchInfo represents a match in a file
type MatchInfo struct {
	LineNum  int
	ColNum   int
	Before   string
	Match    string
	After    string
	Line     string
	// For regex: the full match and submatch indices
	AllMatches [][]int
}

func findMatchesPlain(keyword string, content []byte, path string, cfg Config) []MatchInfo {
	var matches []MatchInfo
	lines := splitLines(content)

	keyBytes := []byte(keyword)
	lineNum := 1

	for _, line := range lines {
		lineStr := string(line)
		offset := 0
		for {
			idx := bytes.Index(line[offset:], keyBytes)
			if idx < 0 {
				break
			}
			absIdx := offset + idx
			before := string(line[:absIdx])
			matchStr := string(line[absIdx : absIdx+len(keyBytes)])
			after := string(line[absIdx+len(keyBytes):])

			m := MatchInfo{
				LineNum: lineNum,
				ColNum:  absIdx,
				Before:  before,
				Match:   matchStr,
				After:   after,
				Line:    lineStr,
			}
			matches = append(matches, m)
			offset = absIdx + len(keyBytes)
		}
		lineNum++
	}

	return matches
}

func findMatchesRegex(pattern *regexp.Regexp, content []byte, path string, cfg Config) []MatchInfo {
	var matches []MatchInfo
	lines := splitLines(content)
	lineNum := 1

	for _, line := range lines {
		lineStr := string(line)

		// Find all matches in this line
		allIdx := pattern.FindAllIndex(line, -1)
		for _, idx := range allIdx {
			start := idx[0]
			end := idx[1]
			before := string(line[:start])
			matchStr := string(line[start:end])
			after := string(line[end:])

			m := MatchInfo{
				LineNum: lineNum,
				ColNum:  start,
				Before:  before,
				Match:   matchStr,
				After:   after,
				Line:    lineStr,
			}
			matches = append(matches, m)
		}
		lineNum++
	}

	return matches
}

func splitLines(content []byte) [][]byte {
	var lines [][]byte
	for {
		idx := bytes.IndexByte(content, '\n')
		if idx < 0 {
			if len(content) > 0 {
				lines = append(lines, content)
			}
			break
		}
		lines = append(lines, content[:idx])
		content = content[idx+1:]
	}
	return lines
}

func displayMatch(m MatchInfo, cfg Config) {
	w := bufio.NewWriter(os.Stdout)

	// Build the "before" part (filename + row:col)
	var prefixParts []string

	if cfg.File {
		prefixParts = append(prefixParts, m.Line[:0]) // placeholder
	}

	var line1 string
	var line2 string

	if cfg.File {
		// Line 1: filename: [row:col:]content
		if cfg.Color {
			line1 = colorGreen + "FILENAME" + colorCyan + ": "
		} else {
			line1 = "FILENAME: "
		}
	}

	// ... (this is getting complex, let me restructure)
	_ = prefixParts
	_ = line1
	_ = line2
	_ = w
}

func formatMatch(m MatchInfo, cfg Config, filePath string) string {
	var buf strings.Builder

	// Compute the prefix (for alignment)
	var prefix string

	if cfg.File {
		if cfg.Row && cfg.Column {
			prefix = fmt.Sprintf("%s: %d:%d:", filePath, m.LineNum, m.ColNum)
		} else if cfg.Row {
			prefix = fmt.Sprintf("%s: %d:", filePath, m.LineNum)
		} else if cfg.Column {
			prefix = fmt.Sprintf("%s: %d:", filePath, m.ColNum)
		} else {
			prefix = fmt.Sprintf("%s: ", filePath)
		}
	} else {
		if cfg.Row && cfg.Column {
			prefix = fmt.Sprintf("%d:%d:", m.LineNum, m.ColNum)
		} else if cfg.Row {
			prefix = fmt.Sprintf("%d:", m.LineNum)
		} else if cfg.Column {
			prefix = fmt.Sprintf("%d:", m.ColNum)
		} else {
			prefix = "    "
		}
	}

	// Arrow padding
	arrowPad := strings.Repeat(" ", len(prefix)-3) + "-> "
	if len(prefix) < 4 {
		arrowPad = " -> "
	}
	if !cfg.File && !cfg.Row && !cfg.Column {
		arrowPad = " -> "
	}

	// Compute replacement text
	replContent := m.Before + "REPLACEMENT" + m.After

	// Line 1: prefix + content
	if cfg.Color {
		// Line 1 parts
		if cfg.File {
			buf.WriteString(colorGreen + filePath + colorCyan)
			if cfg.Row && cfg.Column {
				buf.WriteString(fmt.Sprintf(": %d:%d:", m.LineNum, m.ColNum))
			} else if cfg.Row {
				buf.WriteString(fmt.Sprintf(": %d:", m.LineNum))
			} else if cfg.Column {
				buf.WriteString(fmt.Sprintf(": %d:", m.ColNum))
			} else {
				buf.WriteString(": ")
			}
		} else {
			if cfg.Row && cfg.Column {
				buf.WriteString(fmt.Sprintf("%d:%d:", m.LineNum, m.ColNum))
			} else if cfg.Row {
				buf.WriteString(fmt.Sprintf("%d:", m.LineNum))
			} else if cfg.Column {
				buf.WriteString(fmt.Sprintf("%d:", m.ColNum))
			} else {
				buf.WriteString("    ")
			}
		}
		buf.WriteString(colorWhite + m.Before + colorYellow + m.Match + colorWhite + m.After)
	} else {
		buf.WriteString(prefix + m.Line)
	}

	buf.WriteString("\n")

	// Line 2: arrow + replacement
	if cfg.Color {
		buf.WriteString(colorCyan + arrowPad + colorYellow)
		buf.WriteString(m.Before + "REPLACEMENT" + m.After)
	} else {
		buf.WriteString(arrowPad + replContent)
	}

	_ = replContent

	buf.WriteString("\n")

	return buf.String()
}

func readDecision(reader *bufio.Reader, cfg Config) string {
	// Show prompt
	if cfg.Color {
		fmt.Fprint(os.Stdout, colorCyan+"Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ")
	} else {
		fmt.Fprint(os.Stdout, "Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ")
	}

	line, err := reader.ReadString('\n')
	if err != nil {
		if err == io.EOF {
			return "q"
		}
		return "q"
	}

	// Echo the response
	response := strings.TrimSpace(line)
	if len(response) > 0 {
		fmt.Fprintln(os.Stdout, response)
	}

	return strings.ToLower(response)
}

func replaceSingleMatch(filePath string, m MatchInfo, replacement string, cfg Config, mu *sync.Mutex, tempFiles map[string]string) error {
	// Read current file content
	content, err := os.ReadFile(filePath)
	if err != nil {
		return err
	}

	lines := splitLines(content)
	if m.LineNum < 1 || m.LineNum > len(lines) {
		return fmt.Errorf("line number out of range")
	}

	lineIdx := m.LineNum - 1
	line := lines[lineIdx]

	// Verify the match is still there at the expected position
	keyLen := len(m.Match)
	if m.ColNum+keyLen > len(line) {
		return fmt.Errorf("match no longer at expected position")
	}

	// Replace the specific occurrence
	newLine := string(line[:m.ColNum]) + replacement + string(line[m.ColNum+keyLen:])
	lines[lineIdx] = []byte(newLine)

	// Write to temp file
	tmpPath, err := writeToTemp(filePath, lines, content)
	if err != nil {
		return err
	}

	mu.Lock()
	tempFiles[filePath] = tmpPath
	mu.Unlock()

	// Get original file info for permissions and time
	info, err := os.Stat(filePath)
	if err != nil {
		os.Remove(tmpPath)
		return err
	}

	// Preserve time if requested
	var origTime time.Time
	if cfg.PreserveTime {
		origTime = info.ModTime()
	}

	// Move temp file to original
	err = os.Rename(tmpPath, filePath)
	if err != nil {
		os.Remove(tmpPath)
		return err
	}

	mu.Lock()
	delete(tempFiles, filePath)
	mu.Unlock()

	if cfg.PreserveTime {
		os.Chtimes(filePath, origTime, origTime)
	}

	return nil
}

func replaceAllMatches(filePath, replacement string, cfg Config, pattern *regexp.Regexp, plainKeyword string, mu *sync.Mutex, tempFiles map[string]string) error {
	content, err := os.ReadFile(filePath)
	if err != nil {
		return err
	}

	var newContent []byte
	if cfg.Regex {
		newContent = replaceRegex(pattern, content, replacement)
	} else {
		newContent = bytes.ReplaceAll(content, []byte(plainKeyword), []byte(replacement))
	}

	if bytes.Equal(content, newContent) {
		return nil
	}

	// Write to temp file
	tmpPath := genTempPath(filePath)

	mu.Lock()
	tempFiles[filePath] = tmpPath
	mu.Unlock()

	// Get original file info
	info, err := os.Stat(filePath)
	if err != nil {
		return err
	}

	var origTime time.Time
	if cfg.PreserveTime {
		origTime = info.ModTime()
	}

	err = os.WriteFile(tmpPath, newContent, info.Mode())
	if err != nil {
		return err
	}

	err = os.Rename(tmpPath, filePath)
	if err != nil {
		os.Remove(tmpPath)
		mu.Lock()
		delete(tempFiles, filePath)
		mu.Unlock()
		return err
	}

	mu.Lock()
	delete(tempFiles, filePath)
	mu.Unlock()

	if cfg.PreserveTime {
		os.Chtimes(filePath, origTime, origTime)
	}

	return nil
}

func replaceRegex(pattern *regexp.Regexp, content []byte, replacement string) []byte {
	// Handle $1, ${1}, $name, ${name} backreferences
	return pattern.ReplaceAll(content, buildReplacementTemplate(pattern, replacement))
}

func buildReplacementTemplate(pattern *regexp.Regexp, replacement string) []byte {
	// Convert $name and $1 to Go's ${name} format
	// Go's regexp uses $1 and ${1} already, and also ${name}
	// Rust regex supports $name, ${name}, $1, ${1}
	// We need to handle the conversion

	// For Go regexp: the replacement string uses ${1} for group 1, ${name} for named group
	// Our input may have $name (without braces)

	// Convert $name -> ${name} (but not $$)
	re := regexp.MustCompile(`\$(?:(\d+)|([a-zA-Z_][a-zA-Z0-9_]*))`)
	result := re.ReplaceAllStringFunc(replacement, func(s string) string {
		if s == "$$" {
			return "$$"
		}
		inner := s[1:]
		if inner[0] == '{' {
			return s // already braced
		}
		return "${" + inner + "}"
	})

	return []byte(result)
}

func writeToTemp(filePath string, lines [][]byte, original []byte) (string, error) {
	tmpPath := genTempPath(filePath)

	info, err := os.Stat(filePath)
	if err != nil {
		return "", err
	}

	f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, info.Mode())
	if err != nil {
		return "", err
	}
	defer f.Close()

	// Reconstruct content
	// Detect original line endings
	hasCRLF := bytes.Contains(original, []byte("\r\n"))

	for i, line := range lines {
		if _, err := f.Write(line); err != nil {
			return "", err
		}
		if i < len(lines)-1 {
			if hasCRLF {
				if _, err := f.Write([]byte("\r\n")); err != nil {
					return "", err
				}
			} else {
				if _, err := f.Write([]byte("\n")); err != nil {
					return "", err
				}
			}
		}
	}

	// Add trailing newline if original had one
	if len(original) > 0 && original[len(original)-1] == '\n' {
		if hasCRLF {
			f.Write([]byte("\r\n"))
		} else {
			f.Write([]byte("\n"))
		}
	}

	return tmpPath, nil
}

func genTempPath(filePath string) string {
	dir := filepath.Dir(filePath)
	const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
	b := make([]byte, 6)
	for i := range b {
		b[i] = chars[rand.Intn(len(chars))]
	}
	return filepath.Join(dir, ".tmp"+string(b))
}

func isBinaryFile(path string, checkBytes int) (bool, error) {
	f, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer f.Close()

	buf := make([]byte, checkBytes)
	n, err := f.Read(buf)
	if err != nil && err != io.EOF {
		return false, err
	}

	// Check for null bytes
	for _, b := range buf[:n] {
		if b == 0 {
			return true, nil
		}
	}

	return false, nil
}

func isVCSDir(name string) bool {
	switch name {
	case ".git", ".hg", ".svn", ".bzr":
		return true
	}
	return false
}

func isSymlink(path string) bool {
	info, err := os.Lstat(path)
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeSymlink != 0
}

func collectGitignoreFiles(dir string, files *[]GitignoreFile, parentIgnore bool) {
	// Search for .gitignore files in dir and parents
	if parentIgnore {
		// Walk up to find parent .gitignore files
		current := dir
		var parents []string
		for {
			parent := filepath.Dir(current)
			if parent == current {
				break
			}
			parents = append([]string{parent}, parents...)
			current = parent
		}
		for _, p := range parents {
			loadGitignoreFile(p, files)
		}
	}

	// Load .gitignore in the search directory and subdirs
	loadGitignoreFilesRecursive(dir, files)
}

func loadGitignoreFilesRecursive(dir string, files *[]GitignoreFile) {
	loadGitignoreFile(dir, files)

	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	for _, e := range entries {
		if e.IsDir() && !isVCSDir(e.Name()) {
			loadGitignoreFilesRecursive(filepath.Join(dir, e.Name()), files)
		}
	}
}

func loadGitignoreFile(dir string, files *[]GitignoreFile) {
	gitignorePath := filepath.Join(dir, ".gitignore")
	data, err := os.ReadFile(gitignorePath)
	if err != nil {
		return
	}

	var patterns []GitignorePattern
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		negate := false
		if strings.HasPrefix(line, "!") {
			negate = true
			line = line[1:]
		}

		// Convert glob to regex
		reStr := globToRegex(line)
		re, err := regexp.Compile(reStr)
		if err != nil {
			continue
		}

		patterns = append(patterns, GitignorePattern{
			pattern: line,
			negate:  negate,
			re:      re,
		})
	}

	if len(patterns) > 0 {
		*files = append(*files, GitignoreFile{dir: dir, patterns: patterns})
	}
}

func globToRegex(glob string) string {
	var re strings.Builder
	re.WriteString("(?i)^")

	for i := 0; i < len(glob); i++ {
		c := glob[i]
		switch c {
		case '*':
			if i+1 < len(glob) && glob[i+1] == '*' {
				re.WriteString(".*")
				i++
			} else {
				re.WriteString("[^/]*")
			}
		case '?':
			re.WriteString("[^/]")
		case '.':
			re.WriteString("\\.")
		case '/':
			re.WriteString("/")
		default:
			re.WriteByte(c)
		}
	}

	re.WriteString("(/.*)?$")
	return re.String()
}

func isIgnored(path string, gitignoreFiles []GitignoreFile) bool {
	for _, gf := range gitignoreFiles {
		rel, err := filepath.Rel(gf.dir, path)
		if err != nil {
			continue
		}

		for _, p := range gf.patterns {
			// Check if pattern matches the filename or path
			if p.re.MatchString(rel) || p.re.MatchString(filepath.Base(path)) {
				if p.negate {
					return false
				}
				return true
			}
		}
	}
	return false
}

func formatSkipped(path, reason string, color bool) string {
	var msg string
	switch reason {
	case "binary":
		if color {
			msg = fmt.Sprintf("Skip (binary)    : %q\n", path)
		} else {
			msg = fmt.Sprintf("Skip (binary)    : %q\n", path)
		}
	default:
		msg = fmt.Sprintf("Skip (%s)    : %q\n", reason, path)
	}
	return msg
}

func setupTerminal(colorFlag bool) {
	term := os.Getenv("TERM")

	if !colorFlag || term == "" || term == "dumb" {
		colorEnabled = false
	} else {
		colorEnabled = true
	}

	// Determine termReset based on terminal type
	// For screen/tmux: \x1b[m\x0f
	// For xterm: \x1b(B\x1b[m
	if strings.HasPrefix(term, "screen") || strings.HasPrefix(term, "tmux") {
		termReset = "\x1b[m\x0f"
	} else {
		termReset = "\x1b(B\x1b[m"
	}
}

func getNumCPUs() int {
	// Use runtime.NumCPU() equivalent
	// Read from /proc/cpuinfo or use a reasonable default
	data, err := os.ReadFile("/sys/fs/cgroup/cpu.max")
	if err == nil {
		parts := strings.Fields(string(data))
		if len(parts) >= 2 {
			quota, err1 := strconv.ParseFloat(parts[0], 64)
			period, err2 := strconv.ParseFloat(parts[1], 64)
			if err1 == nil && err2 == nil && period > 0 {
				n := int(quota / period)
				if n > 0 {
					return n
				}
			}
		}
	}

	// Count from /proc/cpuinfo
	data, err = os.ReadFile("/proc/cpuinfo")
	if err == nil {
		count := strings.Count(string(data), "processor\t:")
		if count > 0 {
			return count
		}
	}

	return 8 // fallback
}

func printStats(numThreads int) {
	w := bufio.NewWriter(os.Stdout)

	if colorEnabled {
		fmt.Fprint(w, colorCyan)
	}

	fmt.Fprintln(w, "\nStatistics")
	fmt.Fprintf(w, "  Max threads: %d\n", config.MaxThreads)
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Consumed time ( busy / total )")
	fmt.Fprintf(w, "    Find     : %s / %s\n", 
		formatDuration(stats.findBusy),
		formatDuration(stats.findEnd.Sub(stats.findStart)))

	for i := 0; i < numThreads; i++ {
		if i < len(stats.matchBusy) {
			total := stats.matchEnd[i].Sub(stats.matchStart[i])
			if total < 0 {
				total = 0
			}
			fmt.Fprintf(w, "    Match%02d  : %s / %s\n",
				i,
				formatDuration(stats.matchBusy[i]),
				formatDuration(total))
		}
	}

	fmt.Fprintf(w, "    Sort     : %s / %s\n",
		formatDuration(stats.sortBusy),
		formatDuration(stats.sortEnd.Sub(stats.sortStart)))
	fmt.Fprintf(w, "    Replace  : %s / %s\n",
		formatDuration(stats.replBusy),
		formatDuration(stats.replEnd.Sub(stats.replStart)))

	fmt.Fprintln(w)

	if colorEnabled {
		fmt.Fprint(w, termReset)
		fmt.Fprint(w, termReset)
	}

	w.Flush()
}

func formatDuration(d time.Duration) string {
	if d == 0 {
		return "0s"
	}
	// Show in seconds with variable precision
	secs := d.Seconds()
	if secs >= 1 {
		return fmt.Sprintf("%.0fs", secs)
	}
	// Show in sub-second format
	return fmt.Sprintf("%gs", secs)
}

func printHelp() {
	name := filepath.Base(os.Args[0])
	fmt.Printf(`ambr 0.6.0

USAGE:
    %s [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...

FLAGS:
