func parseArgs(args []string) (Config, string, string, []string, error) {
	cfg := Config{
		Interactive:   true,
		Recursive:     true,
		Symlink:       true,
		Color:         true,
		File:          true,
		SkipVCS:       true,
		SkipGitignore: true,
		FixedOrder:    true,
		ParentIgnore:  true,
		MaxThreads:    20,
		SizePerThread: 1048576,
		BinCheckBytes: 256,
		MmapBytes:     1048576,
	}

	var keyword, replacement string
	var paths []string

	i := 0
	for i < len(args) {
		arg := args[i]

		if strings.HasPrefix(arg, "--") || (len(arg) == 2 && arg[0] == '-') {
			switch arg {
			case "--key-from-file":
				cfg.KeyFromFile = true
			case "--rep-from-file":
				cfg.RepFromFile = true
			case "--verbose":
				cfg.Verbose = true
			case "-r", "--regex":
				cfg.Regex = true
			case "--column":
				cfg.Column = true
			case "--row":
				cfg.Row = true
			case "--binary":
				cfg.Binary = true
			case "--statistics":
				cfg.Statistics = true
			case "--skipped":
				cfg.Skipped = true
			case "--preserve-time":
				cfg.PreserveTime = true
			case "--no-interactive":
				cfg.Interactive = false
			case "--no-recursive":
				cfg.Recursive = false
			case "--no-symlink":
				cfg.Symlink = false
			case "--no-color":
				cfg.Color = false
			case "--no-file":
				cfg.File = false
			case "--no-skip-vcs":
				cfg.SkipVCS = false
			case "--no-skip-gitignore":
				cfg.SkipGitignore = false
			case "--no-fixed-order":
				cfg.FixedOrder = false
			case "--no-parent-ignore":
				cfg.ParentIgnore = false
			case "--tbm", "--sse":
				// Experimental, ignore
			case "-h", "--help":
				printHelp()
				os.Exit(0)
			case "-V", "--version":
				fmt.Printf("ambr %s\n", version)
				os.Exit(0)
			case "--max-threads":
				i++
				if i < len(args) {
					if n, err := strconv.Atoi(args[i]); err == nil {
						cfg.MaxThreads = n
					}
				}
			case "--size-per-thread":
				i++
				if i < len(args) {
					if n, err := strconv.ParseInt(args[i], 10, 64); err == nil {
						cfg.SizePerThread = n
					}
				}
			case "--bin-check-bytes":
				i++
				if i < len(args) {
					if n, err := strconv.Atoi(args[i]); err == nil {
						cfg.BinCheckBytes = n
					}
				}
			case "--mmap-bytes":
				i++
				if i < len(args) {
					if n, err := strconv.ParseInt(args[i], 10, 64); err == nil {
						cfg.MmapBytes = n
					}
				}
			default:
				// Check for --opt=value format
				if idx := strings.Index(arg, "="); idx > 0 {
					key := arg[:idx]
					val := arg[idx+1:]
					switch key {
					case "--max-threads":
						if n, err := strconv.Atoi(val); err == nil {
							cfg.MaxThreads = n
						}
					case "--size-per-thread":
						if n, err := strconv.ParseInt(val, 10, 64); err == nil {
							cfg.SizePerThread = n
						}
					case "--bin-check-bytes":
						if n, err := strconv.Atoi(val); err == nil {
							cfg.BinCheckBytes = n
						}
					case "--mmap-bytes":
						if n, err := strconv.ParseInt(val, 10, 64); err == nil {
							cfg.MmapBytes = n
						}
					}
				}
			}
		} else {
			if keyword == "" {
				keyword = arg
			} else if replacement == "" {
				replacement = arg
			} else {
				paths = append(paths, arg)
			}
		}
		i++
	}

	if keyword == "" {
		printHelp()
		os.Exit(1)
	}
	if replacement == "" {
		printHelp()
		os.Exit(1)
	}

	return cfg, keyword, replacement, paths, nil
}

func setupColor(colorFlag bool, term string) {
	if !colorFlag || term == "" || term == "dumb" {
		colorEnabled = false
		termResetSeq = ""
		return
	}

	colorEnabled = true

	// Determine reset sequence based on terminal type
	if strings.HasPrefix(term, "screen") || strings.HasPrefix(term, "tmux") {
		termResetSeq = "\x1b[m\x0f"
	} else {
		// xterm and others use "(B" prefix
		termResetSeq = "\x1b(B\x1b[m"
	}
}

func dumpTermReset() {
	if colorEnabled {
		fmt.Print(termResetSeq)
		fmt.Print(termResetSeq)
	}
}

func processFile(path string, pattern *regexp.Regexp, plainKeyword string, cfg Config) FileMatches {
	result := FileMatches{Path: path}

	// Check binary
	isBin, err := isBinaryFile(path, cfg.BinCheckBytes)
	if err != nil {
		if cfg.Verbose {
			result.Skipped = true
			result.SkipMsg = fmt.Sprintf("error: %v", err)
		}
		return result
	}

	if isBin && !cfg.Binary {
		result.Skipped = true
		result.SkipMsg = "binary"
		return result
	}

	// Read file
	content, err := os.ReadFile(path)
	if err != nil {
		if cfg.Verbose {
			result.Skipped = true
			result.SkipMsg = fmt.Sprintf("read error: %v", err)
		}
		return result
	}

	// Find matches
	if cfg.Regex && pattern != nil {
		result.Matches = findMatchesRegex(pattern, content)
	} else if plainKeyword != "" {
		result.Matches = findMatchesPlain(plainKeyword, content)
	}

	return result
}

func findMatchesPlain(keyword string, content []byte) []MatchInfo {
	var matches []MatchInfo
	keyBytes := []byte(keyword)
	keyLen := len(keyBytes)

	lineStart := 0
	lineNum := 1

	for lineStart <= len(content) {
		// Find end of line
		lineEnd := bytes.IndexByte(content[lineStart:], '\n')
		var line []byte
		if lineEnd < 0 {
			if lineStart < len(content) {
				line = content[lineStart:]
			} else {
				break
			}
			lineEnd = len(content) - lineStart
		} else {
			line = content[lineStart : lineStart+lineEnd]
		}

		// Search for keyword in this line
		offset := 0
		for {
			idx := bytes.Index(line[offset:], keyBytes)
			if idx < 0 {
				break
			}
			absIdx := offset + idx
			matches = append(matches, MatchInfo{
				LineNum: lineNum,
				ColNum:  absIdx,
				Before:  string(line[:absIdx]),
				Match:   string(line[absIdx : absIdx+keyLen]),
				After:   string(line[absIdx+keyLen:]),
				Line:    string(line),
			})
			offset = absIdx + keyLen
		}

		lineStart += lineEnd + 1
		lineNum++
	}

	return matches
}

func findMatchesRegex(pattern *regexp.Regexp, content []byte) []MatchInfo {
	var matches []MatchInfo

	lineStart := 0
	lineNum := 1

	for lineStart <= len(content) {
		lineEnd := bytes.IndexByte(content[lineStart:], '\n')
		var line []byte
		if lineEnd < 0 {
			if lineStart < len(content) {
				line = content[lineStart:]
			} else {
				break
			}
			lineEnd = len(content) - lineStart
		} else {
			line = content[lineStart : lineStart+lineEnd]
		}

		// Find all matches in this line
		allIdx := pattern.FindAllIndex(line, -1)
		for _, idx := range allIdx {
			start := idx[0]
			end := idx[1]
			matches = append(matches, MatchInfo{
				LineNum: lineNum,
				ColNum:  start,
				Before:  string(line[:start]),
				Match:   string(line[start:end]),
				After:   string(line[end:]),
				Line:    string(line),
			})
		}

		lineStart += lineEnd + 1
		lineNum++
	}

	return matches
}

func computePrefix(path string, m MatchInfo, cfg Config) string {
	if cfg.File {
		if cfg.Row && cfg.Column {
			return fmt.Sprintf("%s: %d:%d:", path, m.LineNum, m.ColNum)
		} else if cfg.Row {
			return fmt.Sprintf("%s: %d:", path, m.LineNum)
		} else if cfg.Column {
			return fmt.Sprintf("%s: %d:", path, m.ColNum)
		} else {
			return path + ": "
		}
	} else {
		if cfg.Row && cfg.Column {
			return fmt.Sprintf("%d:%d:", m.LineNum, m.ColNum)
		} else if cfg.Row {
			return fmt.Sprintf("%d:", m.LineNum)
		} else if cfg.Column {
			return fmt.Sprintf("%d:", m.ColNum)
		} else {
			return "    " // 4 spaces
		}
	}
}

func computeArrowPad(prefix string) string {
	plen := len(prefix)
	if plen < 3 {
		return " -> "
	}
	return strings.Repeat(" ", plen-3) + "-> "
}

func displayMatchLine(w *bufio.Writer, path string, m MatchInfo, replacement string, cfg Config) {
	prefix := computePrefix(path, m, cfg)
	arrowPad := computeArrowPad(prefix)

	// Compute what the replacement would look like
	replLine := m.Before + replacement + m.After

	if colorEnabled {
		// Line 1: color-coded original with match highlighted
		if cfg.File {
			fmt.Fprint(w, colorGreen)
			fmt.Fprint(w, path)
			fmt.Fprint(w, colorCyan)
			if cfg.Row && cfg.Column {
				fmt.Fprintf(w, ": %d:%d:", m.LineNum, m.ColNum)
			} else if cfg.Row {
				fmt.Fprintf(w, ": %d:", m.LineNum)
			} else if cfg.Column {
				fmt.Fprintf(w, ": %d:", m.ColNum)
			} else {
				fmt.Fprint(w, ": ")
			}
		} else {
			if cfg.Row && cfg.Column {
				fmt.Fprintf(w, "%d:%d:", m.LineNum, m.ColNum)
			} else if cfg.Row {
				fmt.Fprintf(w, "%d:", m.LineNum)
			} else if cfg.Column {
				fmt.Fprintf(w, "%d:", m.ColNum)
			} else {
				fmt.Fprint(w, "    ")
			}
		}
		fmt.Fprint(w, colorWhite)
		fmt.Fprint(w, m.Before)
		fmt.Fprint(w, colorYellow)
		fmt.Fprint(w, m.Match)
		fmt.Fprint(w, colorWhite)
		fmt.Fprint(w, m.After)
		fmt.Fprintln(w)

		// Line 2: arrow + replacement
		fmt.Fprint(w, colorCyan)
		fmt.Fprint(w, arrowPad)
		fmt.Fprint(w, colorWhite)
		fmt.Fprint(w, m.Before)
		fmt.Fprint(w, colorYellow)
		fmt.Fprint(w, replacement)
		fmt.Fprint(w, colorWhite)
		fmt.Fprint(w, m.After)
		fmt.Fprintln(w)
	} else {
		// No color
		fmt.Fprint(w, prefix)
		fmt.Fprintln(w, m.Line)
		fmt.Fprint(w, arrowPad)
		fmt.Fprintln(w, replLine)
	}

	// Print prompt
	displayPrompt(w, cfg)
}

func displayPrompt(w *bufio.Writer, cfg Config) {
	if colorEnabled {
		fmt.Fprint(w, colorCyan)
	}
	fmt.Fprint(w, "Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ")
}

func readOneChar() byte {
	// Try to read from stdin first
	b, err := stdinReader.ReadByte()
	if err == nil && b != '\n' && b != '\r' {
		return b
	}
	if err == nil && (b == '\n' || b == '\r') {
		// Skip newlines and try again
		return readOneChar()
	}

	// stdin exhausted, try /dev/tty
	if ttyFile == nil {
		var openErr error
		ttyFile, openErr = os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if openErr != nil {
			return 'q' // Can't open tty, quit
		}
		// Set raw mode
		setRawMode(ttyFile)
	}

	buf := make([]byte, 1)
	n, err := ttyFile.Read(buf)
	if err != nil || n == 0 {
		return ' '
	}
	return buf[0]
}

func setRawMode(f *os.File) {
	var termios Termios
	syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), TCGETS, uintptr(unsafe.Pointer(&termios)))
	termios.Lflag &^= ECHO | ICANON | ISIG
	termios.Cc[6] = 1  // VMIN = 1
	termios.Cc[5] = 0  // VTIME = 0
	syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), TCSETS, uintptr(unsafe.Pointer(&termios)))
}

func doReplaceAll(path, replacement string, cfg Config, pattern *regexp.Regexp, plainKeyword string, mu *sync.Mutex, tempFiles map[string]string) error {
	content, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	var newContent []byte
	if cfg.Regex && pattern != nil {
		newContent = replaceRegex(pattern, content, replacement)
	} else {
		newContent = bytes.ReplaceAll(content, []byte(plainKeyword), []byte(replacement))
	}

	if bytes.Equal(content, newContent) {
		return nil
	}

	return writeFile(path, newContent, cfg, mu, tempFiles)
}

func doReplaceSingle(path string, m MatchInfo, replacement string, cfg Config, pattern *regexp.Regexp, plainKeyword string, mu *sync.Mutex, tempFiles map[string]string) error {
	content, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	// Find the specific line and replace the specific occurrence
	lines := splitLinesKeep(content)
	lineIdx := m.LineNum - 1
	if lineIdx < 0 || lineIdx >= len(lines) {
		return fmt.Errorf("line %d out of range", m.LineNum)
	}

	line := lines[lineIdx]
	lineStr := stripNewline(line)

	// Find the match at the expected position
	var newLineStr string
	if cfg.Regex && pattern != nil {
		// For regex, find the nth occurrence that matches the column
		allIdx := pattern.FindAllStringIndex(lineStr, -1)
		replaced := false
		for _, idx := range allIdx {
			if idx[0] == m.ColNum {
				// This is our match
				replStr := applyRegexReplacement(pattern, lineStr[idx[0]:idx[1]], replacement, lineStr, idx[0])
				newLineStr = lineStr[:idx[0]] + replStr + lineStr[idx[1]:]
				replaced = true
				break
			}
		}
		if !replaced {
			// Match not found at expected position, skip
			return nil
		}
	} else {
		// Plain text
		if m.ColNum+len(m.Match) > len(lineStr) {
			return nil
		}
		if lineStr[m.ColNum:m.ColNum+len(m.Match)] != m.Match {
			return nil
		}
		newLineStr = lineStr[:m.ColNum] + replacement + lineStr[m.ColNum+len(m.Match):]
	}

	// Reconstruct the line with its newline suffix
	var nl string
	if strings.HasSuffix(string(line), "\r\n") {
		nl = "\r\n"
	} else if strings.HasSuffix(string(line), "\n") {
		nl = "\n"
	}
	lines[lineIdx] = []byte(newLineStr + nl)

	// Reconstruct content
	var newContent []byte
	for _, l := range lines {
		newContent = append(newContent, l...)
	}

	// Handle case where original had trailing newline
	// (already handled by splitLinesKeep keeping newlines)

	return writeFile(path, newContent, cfg, mu, tempFiles)
}

func applyRegexReplacement(pattern *regexp.Regexp, matchStr, replacement, line string, matchStart int) string {
	// Build replacement with backreferences
	// Convert $name -> ${name} for Go's regexp
	template := convertReplacementTemplate(replacement)

	// Find the submatch from the full line context
	submatches := pattern.FindStringSubmatch(matchStr)
	if submatches == nil {
		return matchStr
	}

	// Use ReplaceAllStringFunc
	result := pattern.ReplaceAllString(matchStr, template)
	_ = submatches
	return result
}

func replaceRegex(pattern *regexp.Regexp, content []byte, replacement string) []byte {
	template := convertReplacementTemplate(replacement)
	return pattern.ReplaceAll(content, []byte(template))
}

func convertReplacementTemplate(replacement string) string {
	// Convert $name -> ${name} (for named groups without braces)
	// $1 -> $1 (already valid in Go)
	// ${1} -> ${1} (already valid)
	// $name -> ${name}

	var result strings.Builder
	i := 0
	for i < len(replacement) {
		if replacement[i] == '$' && i+1 < len(replacement) {
			if replacement[i+1] == '$' {
				result.WriteString("$$")
				i += 2
				continue
			}
			if replacement[i+1] == '{' {
				// Already braced
				j := i + 2
				for j < len(replacement) && replacement[j] != '}' {
					j++
				}
				if j < len(replacement) {
					result.WriteString(replacement[i : j+1])
					i = j + 1
				} else {
					result.WriteByte(replacement[i])
					i++
				}
				continue
			}
			// Check if next char is digit or letter
			if isAlphaNum(replacement[i+1]) {
				j := i + 1
				for j < len(replacement) && isAlphaNum(replacement[j]) {
					j++
				}
				inner := replacement[i+1 : j]
				// Check if it's pure digits
				isNum := true
				for _, c := range inner {
					if c < '0' || c > '9' {
						isNum = false
						break
					}
				}
				if isNum {
					result.WriteString("$" + inner)
				} else {
					result.WriteString("${" + inner + "}")
				}
				i = j
				continue
			}
		}
		result.WriteByte(replacement[i])
		i++
	}
	return result.String()
}

func isAlphaNum(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

func convertRegexSyntax(pattern string) string {
	// Convert (?<name>...) to (?P<name>...)
	result := regexp.MustCompile(`\(\?<([^>]+)>`).ReplaceAllString(pattern, "(?P<$1>")
	return result
}

func writeFile(path string, content []byte, cfg Config, mu *sync.Mutex, tempFiles map[string]string) error {
	// Get original file info
	info, err := os.Stat(path)
	if err != nil {
		return err
	}

	var origTime time.Time
	if cfg.PreserveTime {
		origTime = info.ModTime()
	}

	// Generate temp file path
	tmpPath := genTempPath(path)

	mu.Lock()
	tempFiles[path] = tmpPath
	mu.Unlock()

	// Write to temp file
	if err := os.WriteFile(tmpPath, content, info.Mode()); err != nil {
		mu.Lock()
		delete(tempFiles, path)
		mu.Unlock()
		return err
	}

	// Atomic rename
	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		mu.Lock()
		delete(tempFiles, path)
		mu.Unlock()
		return err
	}

	mu.Lock()
	delete(tempFiles, path)
	mu.Unlock()

	if cfg.PreserveTime {
		os.Chtimes(path, origTime, origTime)
	}

	return nil
}

func genTempPath(path string) string {
	dir := filepath.Dir(path)
	const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
	b := make([]byte, 6)
	for i := range b {
		b[i] = chars[rand.Intn(len(chars))]
	}
	return filepath.Join(dir, ".tmp"+string(b))
}

func splitLinesKeep(content []byte) [][]byte {
	var lines [][]byte
	start := 0
	for i := 0; i < len(content); i++ {
		if content[i] == '\n' {
			lines = append(lines, content[start:i+1])
			start = i + 1
		}
	}
	if start < len(content) {
		lines = append(lines, content[start:])
	}
	return lines
}

func stripNewline(b []byte) string {
	s := string(b)
	s = strings.TrimRight(s, "\r\n")
	return s
}

func isBinaryFile(path string, checkBytes int) (bool, error) {
	f, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer f.Close()

	buf := make([]byte, checkBytes)
	n, err := f.Read(buf)
	if err != nil && err != io.EOF {
		return false, err
	}

	for i := 0; i < n; i++ {
		if buf[i] == 0 {
			return true, nil
		}
	}

	return false, nil
}

func isVCSDir(name string) bool {
	return name == ".git" || name == ".hg" || name == ".svn" || name == ".bzr"
}

func walkDir(dir string, cfg Config, files *[]string, gitignoreFiles []GitignoreFile) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	for _, entry := range entries {
		name := entry.Name()
		path := filepath.Join(dir, name)

		if entry.IsDir() {
			// Skip VCS directories
			if cfg.SkipVCS && isVCSDir(name) {
				continue
			}

			if !cfg.Recursive {
				continue
			}

			// Follow symlinks?
			if entry.Type()&os.ModeSymlink != 0 {
				if !cfg.Symlink {
					continue
				}
				// Check if it's a dir after following symlink
				realInfo, err := os.Stat(path)
				if err != nil || !realInfo.IsDir() {
					continue
				}
			}

			// Load gitignore in this subdir
			var subdirGitignore []GitignoreFile
			copy(subdirGitignore, gitignoreFiles)
			if cfg.SkipGitignore {
				loadGitignoreFile(path, &subdirGitignore)
			}

			walkDir(path, cfg, files, subdirGitignore)
		} else {
			// Skip symlinks if not following
			if entry.Type()&os.ModeSymlink != 0 && !cfg.Symlink {
				continue
			}

			// Check gitignore
			if cfg.SkipGitignore && isIgnoredByGitignore(path, gitignoreFiles) {
				continue
			}

			*files = append(*files, path)
		}
	}
}

func collectParentGitignoreFiles(dir string, files *[]GitignoreFile) {
	// Walk up the directory tree to find parent .gitignore files
	current, err := filepath.Abs(dir)
	if err != nil {
		return
	}

	var parents []string
	prev := ""
	for current != prev {
		prev = current
		current = filepath.Dir(current)
		if current != prev {
			parents = append([]string{current}, parents...)
		}
	}

	for _, p := range parents {
		loadGitignoreFile(p, files)
	}
}

func collectGitignoreFiles(dir string, cfg Config, files *[]GitignoreFile) {
	loadGitignoreFile(dir, files)
}

func loadGitignoreFile(dir string, files *[]GitignoreFile) {
	gitignorePath := filepath.Join(dir, ".gitignore")
	data, err := os.ReadFile(gitignorePath)
	if err != nil {
		return
	}

	// Notify about found gitignore (per amber's behavior)
	// amber prints: Found .gitignore at the parent directory: "dir"
	// This happens when loading parent gitignore files

	var patterns []GitignorePattern
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimRight(line, "\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		negate := false
		if strings.HasPrefix(line, "!") {
			negate = true
			line = line[1:]
		}

		anchored := false
		if strings.HasPrefix(line, "/") {
			anchored = true
			line = line[1:]
		}

		dirOnly := false
		if strings.HasSuffix(line, "/") {
			dirOnly = true
			line = line[:len(line)-1]
		}

		re := globToRegex(line, anchored)
		if re == nil {
			continue
		}

		patterns = append(patterns, GitignorePattern{
			Pattern:  line,
			Negate:   negate,
			Anchored: anchored,
			DirOnly:  dirOnly,
			Re:       re,
		})
	}

	if len(patterns) > 0 {
		*files = append(*files, GitignoreFile{Dir: dir, Patterns: patterns})
	}
}

func globToRegex(glob string, anchored bool) *regexp.Regexp {
	var re strings.Builder
	re.WriteString("^")

	if !anchored {
		re.WriteString("(.*/)?")
	}

	for i := 0; i < len(glob); i++ {
		c := glob[i]
		switch c {
		case '*':
			if i+1 < len(glob) && glob[i+1] == '*' {
				re.WriteString(".*")
				i++
				// Skip optional /
				if i+1 < len(glob) && glob[i+1] == '/' {
					i++
				}
			} else {
				re.WriteString("[^/]*")
			}
		case '?':
			re.WriteString("[^/]")
		case '.', '+', '(', ')', '{', '}', '[', ']', '^', '$', '|', '\\':
			re.WriteByte('\\')
			re.WriteByte(c)
		default:
			re.WriteByte(c)
		}
	}

	re.WriteString("(/.*)?$")

	compiled, err := regexp.Compile(re.String())
	if err != nil {
		return nil
	}
	return compiled
}

func isIgnoredByGitignore(path string, gitignoreFiles []GitignoreFile) bool {
	for _, gf := range gitignoreFiles {
		rel, err := filepath.Rel(gf.Dir, path)
		if err != nil {
			continue
		}

		// Use forward slashes
		rel = filepath.ToSlash(rel)
		base := filepath.Base(path)

		for _, p := range gf.Patterns {
			matched := p.Re.MatchString(rel) || p.Re.MatchString(base)
			if matched {
				if p.Negate {
					return false
				}
				return true
			}
		}
	}
	return false
}

func printSkipped(w *bufio.Writer, path, reason string) {
	if reason == "binary" {
		fmt.Fprintf(w, "Skip (binary)    : %q\n", path)
	} else {
		fmt.Fprintf(w, "Skip (%s)    : %q\n", reason, path)
	}
}

func getNumCPUs() int {
	// Try cgroup CPU quota
	data, err := os.ReadFile("/sys/fs/cgroup/cpu.max")
	if err == nil {
		parts := strings.Fields(string(bytes.TrimSpace(data)))
		if len(parts) >= 2 && parts[0] != "max" {
			quota, err1 := strconv.ParseFloat(parts[0], 64)
			period, err2 := strconv.ParseFloat(parts[1], 64)
			if err1 == nil && err2 == nil && period > 0 && quota > 0 {
				n := int(quota / period)
				if n > 0 {
					return n
				}
			}
		}
	}

	// Count processors from /proc/cpuinfo
	data, err = os.ReadFile("/proc/cpuinfo")
	if err == nil {
		count := strings.Count(string(data), "processor\t:")
		if count > 0 {
			return count
		}
	}

	return 8
}

func printStatistics(cfg Config) {
	w := bufio.NewWriter(os.Stdout)

	if colorEnabled {
		fmt.Fprint(w, colorCyan)
	}

	fmt.Fprintln(w, "\nStatistics")
	fmt.Fprintf(w, "  Max threads: %d\n", cfg.MaxThreads)
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Consumed time ( busy / total )")
	fmt.Fprintf(w, "    Find     : %s / %s\n",
		formatDuration(statsFindBusy),
		formatDuration(statsFindTotal))

	for i := 0; i < statsNumThreads; i++ {
		if i < len(statsMatchBusy) {
			fmt.Fprintf(w, "    Match%02d  : %s / %s\n",
				i,
				formatDuration(statsMatchBusy[i]),
				formatDuration(statsMatchTotal[i]))
		}
	}

	fmt.Fprintf(w, "    Sort     : %s / %s\n",
		formatDuration(statsSortBusy),
		formatDuration(statsSortTotal))
	fmt.Fprintf(w, "    Replace  : %s / %s\n",
		formatDuration(statsReplBusy),
		formatDuration(statsReplTotal))
	fmt.Fprintln(w)

	if colorEnabled {
		fmt.Fprint(w, termResetSeq)
		fmt.Fprint(w, termResetSeq)
	}

	w.Flush()
}

func formatDuration(d time.Duration) string {
	if d == 0 {
		return "0s"
	}
	s := d.Seconds()
	if s >= 1 {
		return fmt.Sprintf("%.0fs", s)
	}
	// Format like Rust's Duration Display
	// Show as decimal with up to 9 decimal places
	ns := d.Nanoseconds()
	return fmt.Sprintf("%gs", float64(ns)/1e9)
}

