func main() {
	cfg, keyword, replacement, paths := parseArgs()

	// Check TERM
	term := os.Getenv("TERM")
	if term == "" {
		os.Exit(1)
	}

	isDumb = (term == "dumb")

	// Setup color
	// colorEnabled = show inline colors (not just resets)
	if !cfg.Color || isDumb {
		colorEnabled = false
	} else {
		colorEnabled = true
	}

	// Determine reset sequence
	if isDumb {
		termReset = ""
	} else if strings.HasPrefix(term, "screen") || strings.HasPrefix(term, "tmux") {
		termReset = "\x1b[m\x0f"
	} else {
		termReset = "\x1b(B\x1b[m"
	}

	// Setup writers
	stdoutWriter = bufio.NewWriter(os.Stdout)
	stderrWriter = bufio.NewWriter(os.Stderr)

	// Handle key-from-file / rep-from-file
	if cfg.KeyFromFile {
		data, err := os.ReadFile(keyword)
		if err != nil {
			writeError(fmt.Sprintf("permission denied @ %q", keyword))
			flushAndExit(isDumb)
		}
		keyword = string(data)
	}
	if cfg.RepFromFile {
		data, err := os.ReadFile(replacement)
		if err != nil {
			writeError(fmt.Sprintf("permission denied @ %q", replacement))
			flushAndExit(isDumb)
		}
		replacement = string(data)
	}

	// Default paths
	if len(paths) == 0 {
		paths = []string{"."}
	}

	// Compile pattern
	var pattern *regexp.Regexp
	var plainKeyword string
	if cfg.Regex {
		// Convert (?<name>) to (?P<name>)
		kw := regexp.MustCompile(`\(\?<`).ReplaceAllString(keyword, "(?P<")
		var err error
		pattern, err = regexp.Compile(kw)
		if err != nil {
			writeError(fmt.Sprintf("invalid regex: %v", err))
			flushAndExit(isDumb)
		}
	} else {
		plainKeyword = keyword
	}

	// Statistics setup
	findStart := time.Now()

	// Collect files
	var files []string
	type gitignoreInfo struct {
		searchPath string
		files      []*gitignoreFile
	}
	var allGitignores []*gitignoreFile

	for _, searchPath := range paths {
		info, err := os.Lstat(searchPath)
		if err != nil {
			continue
		}

		if !info.IsDir() {
			files = append(files, searchPath)
		} else {
			var gi []*gitignoreFile
			if cfg.SkipGitignore {
				if cfg.ParentIgnore {
					gi = loadParentGitignores(searchPath)
					for _, g := range gi {
						// Notify about parent gitignores
						// We'll print these at the end
						allGitignores = append(allGitignores, g)
					}
				}
			}
			walkDirectory(searchPath, cfg, &files, gi)
		}
	}

	if cfg.Statistics {
		statsFindBusy = time.Since(findStart)
		statsFindEnd = time.Now()
	}

	// Sort files
	if cfg.FixedOrder {
		sort.Strings(files)
	}

	// Determine thread count
	numCPUs := getNumCPUs()
	numThreads := cfg.MaxThreads
	if numThreads > numCPUs {
		numThreads = numCPUs
	}
	if numThreads < 1 {
		numThreads = 1
	}
	statsNumThr = numThreads

	if cfg.Statistics {
		statsMatchBusy = make([]time.Duration, numThreads)
		statsMatchEnd = make([]time.Time, numThreads)
	}

	// Process files in parallel
	resultChan := make(chan FileResult, len(files)+1)
	wg := &sync.WaitGroup{}

	filesPerThread := (len(files) + numThreads - 1) / numThreads
	if filesPerThread < 1 {
		filesPerThread = 1
	}

	for t := 0; t < numThreads; t++ {
		start := t * filesPerThread
		end := start + filesPerThread
		if end > len(files) {
			end = len(files)
		}
		if start >= len(files) {
			break
		}
		wg.Add(1)
		go func(tid int, chunk []string) {
			defer wg.Done()
			ts := time.Now()
			for _, path := range chunk {
				resultChan <- processFile(path, pattern, plainKeyword, cfg)
			}
			if cfg.Statistics {
				e := time.Now()
				statsMu.Lock()
				statsMatchBusy[tid] = e.Sub(ts)
				statsMatchEnd[tid] = e
				statsMu.Unlock()
			}
		}(t, files[start:end])
	}

	go func() {
		wg.Wait()
		close(resultChan)
	}()

	// Collect results
	results := make([]FileResult, 0, len(files))
	for r := range resultChan {
		results = append(results, r)
	}

	// Sort results
	sortStart := time.Now()
	if cfg.FixedOrder {
		sort.Slice(results, func(i, j int) bool {
			return results[i].Path < results[j].Path
		})
	}
	statsSortBusy = time.Since(sortStart)

	// Print skipped files (to stderr)
	if cfg.Skipped {
		for _, r := range results {
			if r.Skipped {
				printSkipped(r.Path, r.SkipMsg)
			}
		}
		stderrWriter.Flush()
	}

	// Setup temp file cleanup on signal
	var tempMu sync.Mutex
	tempFiles := make(map[string]string)

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-sigChan
		tempMu.Lock()
		for _, tmp := range tempFiles {
			os.Remove(tmp)
			fmt.Fprintf(os.Stderr, "Cleanup temporary file: %q\n", tmp)
		}
		tempMu.Unlock()
		finalReset()
		os.Exit(1)
	}()

	// Setup input
	stdinReader = bufio.NewReader(os.Stdin)

	// Replace phase
	replStart := time.Now()
	replaceAll := false

	// When TERM=dumb with colors: suppress all stdout output
	suppress := isDumb && cfg.Color

	for _, result := range results {
		if result.Skipped || len(result.Matches) == 0 {
			continue
		}

		if !cfg.Interactive || replaceAll {
			doReplaceAll(result.Path, replacement, cfg, pattern, plainKeyword, &tempMu, tempFiles)
			continue
		}

		// Interactive mode
		done := false
		for _, m := range result.Matches {
			if done || replaceAll {
				break
			}

			if !suppress {
				printMatch(result.Path, m, replacement, cfg)
				stdoutWriter.Flush()
			}

			// Read decision
			for {
				ch := readChar()

				if !suppress {
					fmt.Fprintf(stdoutWriter, "%c\n", ch)
					stdoutWriter.Flush()
				}

				switch ch {
				case 'y', 'Y':
					doReplaceSingle(result.Path, m, replacement, cfg, pattern, plainKeyword, &tempMu, tempFiles)
					goto nextMatch
				case 'n', 'N':
					goto nextMatch
				case 'a', 'A':
					replaceAll = true
					doReplaceSingle(result.Path, m, replacement, cfg, pattern, plainKeyword, &tempMu, tempFiles)
					goto nextMatch
				case 'q', 'Q':
					done = true
					goto nextMatch
				default:
					// Invalid, re-prompt
					if !suppress {
						printPrompt()
						stdoutWriter.Flush()
					}
				}
			}
		nextMatch:
		}

		if done {
			break
		}
	}

	statsReplBusy = time.Since(replStart)

	// Print gitignore notifications (to stderr)
	for _, gi := range allGitignores {
		printGitignoreNotification(gi)
	}

	// Final resets
	finalReset()

	// Print statistics
	if cfg.Statistics {
		printStatistics(cfg)
	}

	if isDumb {
		os.Exit(1)
	}
	os.Exit(0)
}

func parseArgs() (Config, string, string, []string) {
	cfg := Config{
		Interactive:   true,
		Recursive:     true,
		Symlink:       true,
		Color:         true,
		File:          true,
		SkipVCS:       true,
		SkipGitignore: true,
		FixedOrder:    true,
		ParentIgnore:  true,
		MaxThreads:    20,
		SizePerThread: 1048576,
		BinCheckBytes: 256,
		MmapBytes:     1048576,
	}

	args := os.Args[1:]
	var keyword, replacement string
	var paths []string

	i := 0
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--key-from-file":
			cfg.KeyFromFile = true
		case "--rep-from-file":
			cfg.RepFromFile = true
		case "--verbose":
			cfg.Verbose = true
		case "-r", "--regex":
			cfg.Regex = true
		case "--column":
			cfg.Column = true
		case "--row":
			cfg.Row = true
		case "--binary":
			cfg.Binary = true
		case "--statistics":
			cfg.Statistics = true
		case "--skipped":
			cfg.Skipped = true
		case "--preserve-time":
			cfg.PreserveTime = true
		case "--no-interactive":
			cfg.Interactive = false
		case "--no-recursive":
			cfg.Recursive = false
		case "--no-symlink":
			cfg.Symlink = false
		case "--no-color":
			cfg.Color = false
		case "--no-file":
			cfg.File = false
		case "--no-skip-vcs":
			cfg.SkipVCS = false
		case "--no-skip-gitignore":
			cfg.SkipGitignore = false
		case "--no-fixed-order":
			cfg.FixedOrder = false
		case "--no-parent-ignore":
			cfg.ParentIgnore = false
		case "--tbm", "--sse":
			// ignore
		case "-h", "--help":
			printHelp()
			os.Exit(0)
		case "-V", "--version":
			fmt.Printf("ambr %s\n", version)
			os.Exit(0)
		case "--max-threads":
			i++
			if i < len(args) {
				if n, err := strconv.Atoi(args[i]); err == nil {
					cfg.MaxThreads = n
				}
			}
		case "--size-per-thread":
			i++
			if i < len(args) {
				if n, err := strconv.ParseInt(args[i], 10, 64); err == nil {
					cfg.SizePerThread = n
				}
			}
		case "--bin-check-bytes":
			i++
			if i < len(args) {
				if n, err := strconv.Atoi(args[i]); err == nil {
					cfg.BinCheckBytes = n
				}
			}
		case "--mmap-bytes":
			i++
			if i < len(args) {
				if n, err := strconv.ParseInt(args[i], 10, 64); err == nil {
					cfg.MmapBytes = n
				}
			}
		default:
			if strings.HasPrefix(arg, "-") {
				// handle --opt=val
				if idx := strings.Index(arg, "="); idx > 0 {
					val := arg[idx+1:]
					switch arg[:idx] {
					case "--max-threads":
						if n, err := strconv.Atoi(val); err == nil {
							cfg.MaxThreads = n
						}
					}
				}
			} else {
				if keyword == "" {
					keyword = arg
				} else if replacement == "" {
					replacement = arg
				} else {
					paths = append(paths, arg)
				}
			}
		}
		i++
	}

	if keyword == "" || replacement == "" {
		printHelp()
		os.Exit(1)
	}

	return cfg, keyword, replacement, paths
}

