func processFile(path string, pattern *regexp.Regexp, plainKeyword string, cfg Config) FileResult {
	result := FileResult{Path: path}

	// Check binary
	isBin, err := isBinaryFile(path, cfg.BinCheckBytes)
	if err != nil {
		if cfg.Verbose {
			result.Skipped = true
			result.SkipMsg = fmt.Sprintf("error: %v", err)
		}
		return result
	}

	if isBin && !cfg.Binary {
		result.Skipped = true
		result.SkipMsg = "binary"
		return result
	}

	content, err := os.ReadFile(path)
	if err != nil {
		if cfg.Verbose {
			result.Skipped = true
			result.SkipMsg = fmt.Sprintf("read error: %v", err)
		}
		return result
	}

	if cfg.Regex && pattern != nil {
		result.Matches = findMatchesRegex(pattern, content)
	} else {
		result.Matches = findMatchesPlain(plainKeyword, content)
	}

	return result
}

func findMatchesPlain(keyword string, content []byte) []MatchInfo {
	var matches []MatchInfo
	keyBytes := []byte(keyword)
	klen := len(keyBytes)

	pos := 0
	lineNum := 1
	lineStart := 0

	for pos < len(content) {
		nl := bytes.IndexByte(content[pos:], '\n')
		var lineEnd int
		if nl < 0 {
			lineEnd = len(content)
		} else {
			lineEnd = pos + nl
		}

		line := content[lineStart:lineEnd]
		lineStr := string(line)

		off := 0
		for {
			idx := bytes.Index(line[off:], keyBytes)
			if idx < 0 {
				break
			}
			abs := off + idx
			matches = append(matches, MatchInfo{
				LineNum: lineNum,
				ColNum:  abs,
				Before:  string(line[:abs]),
				Match:   string(line[abs : abs+klen]),
				After:   string(line[abs+klen:]),
				Line:    lineStr,
			})
			off = abs + klen
		}

		if nl < 0 {
			break
		}
		lineStart = lineEnd + 1
		pos = lineStart
		lineNum++
	}

	return matches
}

func findMatchesRegex(pattern *regexp.Regexp, content []byte) []MatchInfo {
	var matches []MatchInfo

	pos := 0
	lineNum := 1
	lineStart := 0

	for pos < len(content) {
		nl := bytes.IndexByte(content[pos:], '\n')
		var lineEnd int
		if nl < 0 {
			lineEnd = len(content)
		} else {
			lineEnd = pos + nl
		}

		line := content[lineStart:lineEnd]
		lineStr := string(line)

		for _, idx := range pattern.FindAllIndex(line, -1) {
			start, end := idx[0], idx[1]
			matches = append(matches, MatchInfo{
				LineNum: lineNum,
				ColNum:  start,
				Before:  string(line[:start]),
				Match:   string(line[start:end]),
				After:   string(line[end:]),
				Line:    lineStr,
			})
		}

		if nl < 0 {
			break
		}
		lineStart = lineEnd + 1
		pos = lineStart
		lineNum++
	}

	return matches
}

func computePrefix(path string, m MatchInfo, cfg Config) string {
	if cfg.File {
		if cfg.Row && cfg.Column {
			return fmt.Sprintf("%s: %d:%d:", path, m.LineNum, m.ColNum)
		} else if cfg.Row {
			return fmt.Sprintf("%s: %d:", path, m.LineNum)
		} else if cfg.Column {
			return fmt.Sprintf("%s: %d:", path, m.ColNum)
		}
		return path + ": "
	}
	if cfg.Row && cfg.Column {
		return fmt.Sprintf("%d:%d:", m.LineNum, m.ColNum)
	} else if cfg.Row {
		return fmt.Sprintf("%d:", m.LineNum)
	} else if cfg.Column {
		return fmt.Sprintf("%d:", m.ColNum)
	}
	return "    "
}

func printMatch(path string, m MatchInfo, replacement string, cfg Config) {
	prefix := computePrefix(path, m, cfg)

	plen := len(prefix)
	arrowPad := strings.Repeat(" ", plen-3) + "-> "
	if plen < 4 {
		arrowPad = " -> "
	}

	if colorEnabled {
		// Line 1
		if cfg.File {
			fmt.Fprint(stdoutWriter, colorGreen+path+colorCyan)
			if cfg.Row && cfg.Column {
				fmt.Fprintf(stdoutWriter, ": %d:%d:", m.LineNum, m.ColNum)
			} else if cfg.Row {
				fmt.Fprintf(stdoutWriter, ": %d:", m.LineNum)
			} else if cfg.Column {
				fmt.Fprintf(stdoutWriter, ": %d:", m.ColNum)
			} else {
				fmt.Fprint(stdoutWriter, ": ")
			}
		} else {
			if cfg.Row && cfg.Column {
				fmt.Fprintf(stdoutWriter, "%d:%d:", m.LineNum, m.ColNum)
			} else if cfg.Row {
				fmt.Fprintf(stdoutWriter, "%d:", m.LineNum)
			} else if cfg.Column {
				fmt.Fprintf(stdoutWriter, "%d:", m.ColNum)
			} else {
				fmt.Fprint(stdoutWriter, "    ")
			}
		}
		fmt.Fprint(stdoutWriter, colorWhite+m.Before+colorYellow+m.Match+colorWhite+m.After)
		fmt.Fprintln(stdoutWriter)
		// Line 2
		fmt.Fprint(stdoutWriter, colorCyan+arrowPad+colorWhite+m.Before+colorYellow+replacement+colorWhite+m.After)
		fmt.Fprintln(stdoutWriter)
	} else {
		// No color
		fmt.Fprint(stdoutWriter, prefix+m.Line)
		fmt.Fprintln(stdoutWriter)
		fmt.Fprint(stdoutWriter, arrowPad+m.Before+replacement+m.After)
		fmt.Fprintln(stdoutWriter)
	}

	printPrompt()
}

func printPrompt() {
	if colorEnabled {
		fmt.Fprint(stdoutWriter, colorCyan)
	}
	fmt.Fprint(stdoutWriter, "Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ")
}

func readChar() byte {
	// Try stdin first
	b, err := stdinReader.ReadByte()
	if err == nil {
		if b == '\n' || b == '\r' {
			return readChar()
		}
		return b
	}

	// stdin EOF, try /dev/tty
	if ttyFile == nil {
		f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err != nil {
			return 'q'
		}
		ttyFile = f
		setRawMode(f)
	}

	buf := [1]byte{}
	n, err := ttyFile.Read(buf[:])
	if err != nil || n == 0 {
		return ' '
	}
	return buf[0]
}

func setRawMode(f *os.File) {
	var t termios
	syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), tcgets, uintptr(unsafe.Pointer(&t)))
	t.Lflag &^= 0x8 | 0x2 | 0x1 // ECHO | ICANON | ISIG
	t.Cc[6] = 1  // VMIN
	t.Cc[5] = 0  // VTIME
	syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), tcsets, uintptr(unsafe.Pointer(&t)))
}

func doReplaceAll(path, replacement string, cfg Config, pattern *regexp.Regexp, plainKeyword string, mu *sync.Mutex, tempFiles map[string]string) {
	content, err := os.ReadFile(path)
	if err != nil {
		return
	}

	var newContent []byte
	if cfg.Regex && pattern != nil {
		newContent = regexReplace(pattern, content, replacement)
	} else {
		newContent = bytes.ReplaceAll(content, []byte(plainKeyword), []byte(replacement))
	}

	if bytes.Equal(content, newContent) {
		return
	}

	atomicWrite(path, newContent, cfg, mu, tempFiles)
}

func doReplaceSingle(path string, m MatchInfo, replacement string, cfg Config, pattern *regexp.Regexp, plainKeyword string, mu *sync.Mutex, tempFiles map[string]string) {
	content, err := os.ReadFile(path)
	if err != nil {
		return
	}

	// Find the line
	lines := splitLinesKeep(content)
	if m.LineNum < 1 || m.LineNum > len(lines) {
		return
	}

	lineIdx := m.LineNum - 1
	lineWithNL := lines[lineIdx]
	lineStr := strings.TrimRight(string(lineWithNL), "\r\n")

	// Compute new line content
	var newLineStr string
	if cfg.Regex && pattern != nil {
		// Find match at ColNum
		allIdx := pattern.FindAllStringIndex(lineStr, -1)
		for _, idx := range allIdx {
			if idx[0] == m.ColNum {
				repl := regexReplaceStr(pattern, lineStr[idx[0]:idx[1]], replacement)
				newLineStr = lineStr[:idx[0]] + repl + lineStr[idx[1]:]
				break
			}
		}
		if newLineStr == "" {
			newLineStr = lineStr
		}
	} else {
		if m.ColNum+len(m.Match) > len(lineStr) {
			return
		}
		if lineStr[m.ColNum:m.ColNum+len(m.Match)] != m.Match {
			return
		}
		newLineStr = lineStr[:m.ColNum] + replacement + lineStr[m.ColNum+len(m.Match):]
	}

	// Preserve line ending
	var nl string
	raw := string(lineWithNL)
	if strings.HasSuffix(raw, "\r\n") {
		nl = "\r\n"
	} else if strings.HasSuffix(raw, "\n") {
		nl = "\n"
	}
	lines[lineIdx] = []byte(newLineStr + nl)

	// Reconstruct
	var newContent []byte
	for _, l := range lines {
		newContent = append(newContent, l...)
	}

	atomicWrite(path, newContent, cfg, mu, tempFiles)
}

func regexReplace(pattern *regexp.Regexp, content []byte, replacement string) []byte {
	tmpl := convertReplacement(replacement)
	return pattern.ReplaceAll(content, []byte(tmpl))
}

func regexReplaceStr(pattern *regexp.Regexp, src, replacement string) string {
	tmpl := convertReplacement(replacement)
	return pattern.ReplaceAllString(src, tmpl)
}

func convertReplacement(repl string) string {
	var sb strings.Builder
	i := 0
	for i < len(repl) {
		c := repl[i]
		if c == '$' && i+1 < len(repl) {
			next := repl[i+1]
			if next == '$' {
				sb.WriteString("$$")
				i += 2
				continue
			}
			if next == '{' {
				// Already braced
				j := i + 2
				for j < len(repl) && repl[j] != '}' {
					j++
				}
				if j < len(repl) {
					sb.WriteString(repl[i : j+1])
					i = j + 1
					continue
				}
			}
			if isAlphaNumU(next) {
				j := i + 1
				for j < len(repl) && isAlphaNumU(repl[j]) {
					j++
				}
				inner := repl[i+1 : j]
				// If it's all digits: $1, $12 -> keep as-is
				allDig := true
				for _, c2 := range inner {
					if c2 < '0' || c2 > '9' {
						allDig = false
						break
					}
				}
				if allDig {
					sb.WriteString("$" + inner)
				} else {
					sb.WriteString("${" + inner + "}")
				}
				i = j
				continue
			}
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String()
}

func isAlphaNumU(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

func atomicWrite(path string, content []byte, cfg Config, mu *sync.Mutex, tempFiles map[string]string) {
	info, err := os.Stat(path)
	if err != nil {
		return
	}

	var origMtime time.Time
	if cfg.PreserveTime {
		origMtime = info.ModTime()
	}

	tmpPath := genTempPath(path)

	mu.Lock()
	tempFiles[path] = tmpPath
	mu.Unlock()

	if err := os.WriteFile(tmpPath, content, info.Mode()); err != nil {
		mu.Lock()
		delete(tempFiles, path)
		mu.Unlock()
		return
	}

	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		mu.Lock()
		delete(tempFiles, path)
		mu.Unlock()
		return
	}

	mu.Lock()
	delete(tempFiles, path)
	mu.Unlock()

	if cfg.PreserveTime {
		os.Chtimes(path, origMtime, origMtime)
	}
}

func genTempPath(path string) string {
	dir := filepath.Dir(path)
	const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
	b := make([]byte, 6)
	for i := range b {
		b[i] = chars[rand.Intn(len(chars))]
	}
	return filepath.Join(dir, ".tmp"+string(b))
}

func splitLinesKeep(content []byte) [][]byte {
	var lines [][]byte
	start := 0
	for i := 0; i < len(content); i++ {
		if content[i] == '\n' {
			lines = append(lines, content[start:i+1])
			start = i + 1
		}
	}
	if start < len(content) {
		lines = append(lines, content[start:])
	}
	return lines
}

func isBinaryFile(path string, checkBytes int) (bool, error) {
	f, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer f.Close()

	buf := make([]byte, checkBytes)
	n, err := f.Read(buf)
	if err != nil && err != io.EOF {
		return false, err
	}

	for i := 0; i < n; i++ {
		if buf[i] == 0 {
			return true, nil
		}
	}
	return false, nil
}

type gitignoreFile struct {
	dir      string
	patterns []gitignorePattern
}

type gitignorePattern struct {
	negate bool
	re     *regexp.Regexp
}

func loadParentGitignores(searchPath string) []*gitignoreFile {
	abs, err := filepath.Abs(searchPath)
	if err != nil {
		return nil
	}

	var result []*gitignoreFile
	current := filepath.Dir(abs)

	for {
		parent := filepath.Dir(current)
		if parent == current {
			break
		}

		gi := loadGitignoreFile(current)
		if gi != nil {
			result = append(result, gi)
		}

		current = parent
	}

	return result
}

func loadGitignoreFile(dir string) *gitignoreFile {
	path := filepath.Join(dir, ".gitignore")
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}

	gi := &gitignoreFile{dir: dir}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimRight(line, "\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		negate := false
		if strings.HasPrefix(line, "!") {
			negate = true
			line = line[1:]
		}

		anchored := strings.HasPrefix(line, "/")
		if anchored {
			line = line[1:]
		}

		if strings.HasSuffix(line, "/") {
			line = line[:len(line)-1]
		}

		re := buildGlobRegex(line, anchored)
		if re == nil {
			continue
		}
		gi.patterns = append(gi.patterns, gitignorePattern{negate: negate, re: re})
	}

	if len(gi.patterns) == 0 {
		return nil
	}
	return gi
}

func buildGlobRegex(glob string, anchored bool) *regexp.Regexp {
	var sb strings.Builder
	sb.WriteString("^")
	if !anchored {
		sb.WriteString("(.*/)?")
	}

	for i := 0; i < len(glob); i++ {
		c := glob[i]
		switch c {
		case '*':
			if i+1 < len(glob) && glob[i+1] == '*' {
				sb.WriteString(".*")
				i++
				if i+1 < len(glob) && glob[i+1] == '/' {
					i++
				}
			} else {
				sb.WriteString("[^/]*")
			}
		case '?':
			sb.WriteString("[^/]")
		case '.', '+', '(', ')', '[', ']', '{', '}', '\\', '^', '$', '|':
			sb.WriteByte('\\')
			sb.WriteByte(c)
		default:
			sb.WriteByte(c)
		}
	}
	sb.WriteString("(/.*)?$")

	re, err := regexp.Compile(sb.String())
	if err != nil {
		return nil
	}
	return re
}

func isIgnored(path string, gitignores []*gitignoreFile) bool {
	for _, gi := range gitignores {
		rel, err := filepath.Rel(gi.dir, path)
		if err != nil {
			continue
		}
		rel = filepath.ToSlash(rel)
		base := filepath.Base(path)

		for _, p := range gi.patterns {
			if p.re.MatchString(rel) || p.re.MatchString(base) {
				if p.negate {
					return false
				}
				return true
			}
		}
	}
	return false
}

func walkDirectory(dir string, cfg Config, files *[]string, parentGitignores []*gitignoreFile) {
	// Load gitignore in this directory
	var gi []*gitignoreFile
	gi = append(gi, parentGitignores...)
	if cfg.SkipGitignore {
		dirGi := loadGitignoreFile(dir)
		if dirGi != nil {
			gi = append(gi, dirGi)
		}
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	for _, entry := range entries {
		name := entry.Name()
		path := filepath.Join(dir, name)

		if entry.IsDir() {
			if cfg.SkipVCS && isVCSDir(name) {
				continue
			}
			if !cfg.Recursive {
				continue
			}

			// Check if symlink
			if entry.Type()&os.ModeSymlink != 0 {
				if !cfg.Symlink {
					continue
				}
				realInfo, err := os.Stat(path)
				if err != nil || !realInfo.IsDir() {
					continue
				}
			}

			walkDirectory(path, cfg, files, gi)
		} else {
			if entry.Type()&os.ModeSymlink != 0 && !cfg.Symlink {
				continue
			}
			if cfg.SkipGitignore && isIgnored(path, gi) {
				continue
			}
			*files = append(*files, path)
		}
	}
}

func isVCSDir(name string) bool {
	return name == ".git" || name == ".hg" || name == ".svn" || name == ".bzr"
}

func printSkipped(path, reason string) {
	if colorEnabled {
		fmt.Fprint(stderrWriter, colorCyan)
	}
	if reason == "binary" {
		fmt.Fprintf(stderrWriter, "Skip (binary)    : %q\n", path)
	} else {
		fmt.Fprintf(stderrWriter, "Skip (%s): %q\n", reason, path)
	}
	if isDumb && !colorEnabled {
		// no reset for dumb+nocolor
	}
}

func printGitignoreNotification(gi *gitignoreFile) {
	// Build the "search_path/.." path
	// This message appears on stderr
	// We need the original search path. For now, just show the dir.
	if colorEnabled {
		fmt.Fprint(stderrWriter, colorCyan)
	}
	// The path shown is the gitignore dir as seen from the search path
	// This is complex to implement correctly. For now, skip it.
	_ = gi
}

func writeError(msg string) {
	if colorEnabled {
		fmt.Fprint(stderrWriter, colorRed)
	}
	fmt.Fprintf(stderrWriter, "Error: %s\n\n", msg)
}

func finalReset() {
	if termReset == "" {
		return
	}
	// Reset stdout
	fmt.Fprint(stdoutWriter, termReset)
	stdoutWriter.Flush()
	// Reset stderr
	fmt.Fprint(stderrWriter, termReset)
	stderrWriter.Flush()
}

func flushAndExit(dumb bool) {
	finalReset()
	if dumb {
		os.Exit(1)
	}
	os.Exit(1)
}

func getNumCPUs() int {
	data, err := os.ReadFile("/sys/fs/cgroup/cpu.max")
	if err == nil {
		parts := strings.Fields(string(bytes.TrimSpace(data)))
		if len(parts) >= 2 && parts[0] != "max" {
			q, e1 := strconv.ParseFloat(parts[0], 64)
			p, e2 := strconv.ParseFloat(parts[1], 64)
			if e1 == nil && e2 == nil && p > 0 && q > 0 {
				n := int(q / p)
				if n > 0 {
					return n
				}
			}
		}
	}

	data, err = os.ReadFile("/proc/cpuinfo")
	if err == nil {
		n := strings.Count(string(data), "processor\t:")
		if n > 0 {
			return n
		}
	}
	return 8
}

func printStatistics(cfg Config) {
	w := bufio.NewWriter(os.Stdout)
	if colorEnabled {
		fmt.Fprint(w, colorCyan)
	}
	fmt.Fprintln(w, "\nStatistics")
	fmt.Fprintf(w, "  Max threads: %d\n", cfg.MaxThreads)
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Consumed time ( busy / total )")
	fmt.Fprintf(w, "    Find     : %s / %s\n", fmtDur(statsFindBusy), fmtDur(statsFindBusy))
	for i := 0; i < statsNumThr; i++ {
		var busy, total time.Duration
		if i < len(statsMatchBusy) {
			busy = statsMatchBusy[i]
			total = statsMatchBusy[i]
		}
		fmt.Fprintf(w, "    Match%02d  : %s / %s\n", i, fmtDur(busy), fmtDur(total))
	}
	fmt.Fprintf(w, "    Sort     : %s / %s\n", fmtDur(statsSortBusy), fmtDur(statsSortBusy))
	fmt.Fprintf(w, "    Replace  : %s / %s\n", fmtDur(statsReplBusy), fmtDur(statsReplBusy))
	fmt.Fprintln(w)
	if termReset != "" {
		fmt.Fprint(w, termReset)
		fmt.Fprint(w, termReset)
	}
	w.Flush()
}

func fmtDur(d time.Duration) string {
	if d == 0 {
		return "0s"
	}
	ns := d.Nanoseconds()
	s := float64(ns) / 1e9
	if s >= 1.0 {
		return fmt.Sprintf("%.0fs", s)
	}
	return fmt.Sprintf("%gs", s)
}
