func processFile(path string, pattern *regexp.Regexp, plainKeyword string, cfg Config) FileResult {
	result := FileResult{Path: path}

	// Check binary
	isBin, err := isBinaryFile(path, cfg.BinCheckBytes)
	if err != nil {
		if cfg.Verbose {
			result.Skipped = true
			result.SkipMsg = fmt.Sprintf("error: %v", err)
		}
		return result
	}

	if isBin && !cfg.Binary {
		result.Skipped = true
		result.SkipMsg = "binary"
		return result
	}

	content, err := os.ReadFile(path)
	if err != nil {
		if cfg.Verbose {
			result.Skipped = true
			result.SkipMsg = fmt.Sprintf("read error: %v", err)
		}
		return result
	}

	if cfg.Regex && pattern != nil {
		result.Matches = findMatchesRegex(pattern, content)
	} else {
		result.Matches = findMatchesPlain(plainKeyword, content)
	}

	return result
}

func findMatchesPlain(keyword string, content []byte) []MatchInfo {
	var matches []MatchInfo
	keyBytes := []byte(keyword)
	klen := len(keyBytes)

	pos := 0
	lineNum := 1
	lineStart := 0

	for pos < len(content) {
		nl := bytes.IndexByte(content[pos:], '\n')
		var lineEnd int
		if nl < 0 {
			lineEnd = len(content)
		} else {
			lineEnd = pos + nl
		}

		line := content[lineStart:lineEnd]
		lineStr := string(line)

		off := 0
		for {
			idx := bytes.Index(line[off:], keyBytes)
			if idx < 0 {
				break
			}
			abs := off + idx
			matches = append(matches, MatchInfo{
				LineNum: lineNum,
				ColNum:  abs,
				Before:  string(line[:abs]),
				Match:   string(line[abs : abs+klen]),
				After:   string(line[abs+klen:]),
				Line:    lineStr,
			})
			off = abs + klen
		}

		if nl < 0 {
			break
		}
		lineStart = lineEnd + 1
		pos = lineStart
		lineNum++
	}

	return matches
}

func findMatchesRegex(pattern *regexp.Regexp, content []byte) []MatchInfo {
	var matches []MatchInfo

	pos := 0
	lineNum := 1
	lineStart := 0

	for pos < len(content) {
		nl := bytes.IndexByte(content[pos:], '\n')
		var lineEnd int
		if nl < 0 {
			lineEnd = len(content)
		} else {
			lineEnd = pos + nl
		}

		line := content[lineStart:lineEnd]
		lineStr := string(line)

		for _, idx := range pattern.FindAllIndex(line, -1) {
			start, end := idx[0], idx[1]
			matches = append(matches, MatchInfo{
				LineNum: lineNum,
				ColNum:  start,
				Before:  string(line[:start]),
				Match:   string(line[start:end]),
				After:   string(line[end:]),
				Line:    lineStr,
			})
		}

		if nl < 0 {
			break
		}
		lineStart = lineEnd + 1
		pos = lineStart
		lineNum++
	}

	return matches
}

func computePrefix(path string, m MatchInfo, cfg Config) string {
	if cfg.File {
		if cfg.Row && cfg.Column {
			return fmt.Sprintf("%s: %d:%d:", path, m.LineNum, m.ColNum)
		} else if cfg.Row {
			return fmt.Sprintf("%s: %d:", path, m.LineNum)
		} else if cfg.Column {
			return fmt.Sprintf("%s: %d:", path, m.ColNum)
		}
		return path + ": "
	}
	if cfg.Row && cfg.Column {
		return fmt.Sprintf("%d:%d:", m.LineNum, m.ColNum)
	} else if cfg.Row {
		return fmt.Sprintf("%d:", m.LineNum)
	} else if cfg.Column {
		return fmt.Sprintf("%d:", m.ColNum)
	}
	return "    "
}

